insert into public.recipes (title_en, title_km, description_en, description_km, calories, cuisine, category, prep_minutes, servings, difficulty, is_trending, popularity, image_url, image_credit, image_page, ingredients_en, ingredients_km, steps_en, steps_km) values
('Pho Bo', 'ផើសាច់គោ', 'Vietnamese beef noodle soup with a star anise and ginger broth.', 'គុយទាវសាច់គោវៀតណាម ជាមួយទឹកស៊ុបផ្កាចន្ទ និងខ្ញី។', 420, 'VN', 'noodles', 90, 4, 'hard', false, 70, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/6/65/Beef_noodle_soup_%28Ph%E1%BB%9F_b%C3%B2%29_-_Pho_Hanoi_Authentic_2024-12-01.jpg/500px-Beef_noodle_soup_%28Ph%E1%BB%9F_b%C3%B2%29_-_Pho_Hanoi_Authentic_2024-12-01.jpg', 'Photo: Andy Li, CC0, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Beef_noodle_soup_(Ph%E1%BB%9F_b%C3%B2)_-_Pho_Hanoi_Authentic_2024-12-01.jpg', '["1 kg beef bones", "400 g rice noodles", "2 star anise and 1 cinnamon stick", "1 piece ginger", "200 g thin beef slices", "Herbs, bean sprouts and lime"]'::jsonb, '["ឆ្អឹងគោ ១ គីឡូក្រាម", "គុយទាវ ៤០០ ក្រាម", "ផ្កាចន្ទ ២ និងសំបកឈើក្រអូប ១", "ខ្ញី ១ ដុំ", "សាច់គោហាន់ស្តើង ២០០ ក្រាម", "ជីរ សណ្តែកបណ្តុះ និងក្រូចឆ្មា"]'::jsonb, '["Cover the beef bones with cold water, boil hard for 5 minutes, then drain and rinse them clean.", "Char the ginger over a flame or under the grill until blackened in spots, then slice it.", "Toast the star anise and cinnamon in a dry pan for 1 minute until fragrant.", "Put the bones, ginger and spices in a big pot with 3 litres of water and bring to the boil.", "Simmer uncovered on very low heat for at least 2 hours, skimming off foam; season with salt and a little sugar.", "Strain the broth and keep it boiling.", "Soak the rice noodles, then blanch them for 20 seconds and divide between bowls.", "Lay the raw beef slices on top and pour the boiling broth over; the heat cooks the beef.", "Serve with the herbs, bean sprouts and lime on the side."]'::jsonb, '["ដាក់ឆ្អឹងគោក្នុងទឹកត្រជាក់ ស្ងោរខ្លាំង ៥ នាទី រួចចាក់ចោល ហើយលាងឱ្យស្អាត។", "អាំងខ្ញីលើភ្លើងរហូតខ្មៅខ្លះ ហើយហាន់។", "លីងផ្កាចន្ទ និងសំបកឈើក្រអូបក្នុងខ្ទះស្ងួត ១ នាទី រហូតឈ្ងុយ។", "ដាក់ឆ្អឹង ខ្ញី និងគ្រឿងទេសក្នុងឆ្នាំងធំ ជាមួយទឹក ៣ លីត្រ ហើយស្ងោរឱ្យពុះ។", "រំងាស់ភ្លើងតិចបំផុតយ៉ាងតិច ២ ម៉ោង ដោយមិនគ្រប ដួសពពុះចេញ ដាក់អំបិល និងស្ករបន្តិច។", "ចម្រោះទឹកស៊ុប ហើយទុកឱ្យពុះជាប់។", "ត្រាំគុយទាវ រួចស្រុះ ២០ វិនាទី ហើយចែកដាក់ចាន។", "ដាក់សាច់គោឆៅពីលើ ហើយស្រោចទឹកស៊ុបពុះ កម្តៅនឹងធ្វើឱ្យសាច់ឆ្អិន។", "ញ៉ាំជាមួយជីរ សណ្តែកបណ្តុះ និងក្រូចឆ្មា។"]'::jsonb),
('Banh Xeo', 'នំបាញ់ឆែវ', 'Crispy turmeric rice pancake filled with shrimp, pork and bean sprouts.', 'នំបាញ់ឆែវម្សៅអង្ករលាយរមៀតស្រួយ ញាត់បង្គា សាច់ជ្រូក និងសណ្តែកបណ្តុះ។', 410, 'VN', 'snack', 40, 4, 'medium', true, 69, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/3/32/Crispy_Vietnamese_Pancake_%28Banh_Xeo%29_-_Xin_Chao%2C_Eastbourne_2026-08-14_%281%29.jpg/500px-Crispy_Vietnamese_Pancake_%28Banh_Xeo%29_-_Xin_Chao%2C_Eastbourne_2026-08-14_%281%29.jpg', 'Photo: Andy Li, CC0, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Crispy_Vietnamese_Pancake_(Banh_Xeo)_-_Xin_Chao,_Eastbourne_2026-08-14_(1).jpg', '["200 g rice flour", "200 ml coconut milk", "1 tsp turmeric", "150 g shrimp", "100 g pork belly", "Bean sprouts and lettuce"]'::jsonb, '["ម្សៅអង្ករ ២០០ ក្រាម", "ខ្ទិះដូង ២០០ មីលីលីត្រ", "ម្សៅរមៀត ១ ស្លាបព្រាកាហ្វេ", "បង្គា ១៥០ ក្រាម", "សាច់ជ្រូកបីជាន់ ១០០ ក្រាម", "សណ្តែកបណ្តុះ និងសាឡាត់"]'::jsonb, '["Whisk the rice flour, turmeric, a pinch of salt, the coconut milk and about 250 ml water into a thin batter; rest 30 minutes.", "Slice the pork belly thinly; peel the shrimp.", "Heat a non-stick pan on medium-high heat with 1 tsp oil.", "Fry a few slices of pork for 1 minute, then add 3 or 4 shrimp and cook until pink.", "Pour in a ladle of batter and swirl quickly so it covers the pan thinly; it should sizzle.", "Scatter bean sprouts on one half, cover and cook 2 minutes.", "Uncover and cook 2 to 3 more minutes until the edges are brown and crisp, then fold in half.", "Slide onto a plate and repeat with the rest. Wrap pieces in lettuce to eat."]'::jsonb, '["វាយម្សៅអង្ករ រមៀត អំបិលបន្តិច ខ្ទិះដូង និងទឹកប្រហែល ២៥០ មីលីលីត្រ ឱ្យរាវ ហើយទុក ៣០ នាទី។", "ហាន់សាច់ជ្រូកបីជាន់ស្តើងៗ ហើយបកបង្គា។", "កម្តៅខ្ទះមិនស្អិតលើភ្លើងខ្លាំងមធ្យម ជាមួយប្រេង ១ ស្លាបព្រាកាហ្វេ។", "ចៀនសាច់ជ្រូកពីរបីបន្ទះ ១ នាទី រួចដាក់បង្គា ៣ ឬ ៤ រហូតក្រហម។", "ចាក់ម្សៅមួយវែក ហើយគ្រវីឱ្យរាលស្តើងពេញខ្ទះ ត្រូវតែឮសូរឆ្អេះ។", "រោយសណ្តែកបណ្តុះលើពាក់កណ្តាល គ្រប ហើយចម្អិន ២ នាទី។", "បើកគម្រប ចម្អិន ២ ទៅ ៣ នាទីទៀត រហូតគែមលឿងស្រួយ រួចបត់ពាក់កណ្តាល។", "រំកិលដាក់ចាន ហើយធ្វើបន្តទៀត។ ខ្ចប់ជាមួយសាឡាត់ពេលញ៉ាំ។"]'::jsonb),
('Ca Phe Sua Da', 'កាហ្វេទឹកដោះគោទឹកកក', 'Strong drip coffee with sweet condensed milk over ice.', 'កាហ្វេដាំខ្លាំង ជាមួយទឹកដោះគោខាប់ និងទឹកកក។', 190, 'VN', 'drinks', 10, 1, 'easy', false, 68, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/e/ec/Ca_Phe_Sua_Da.jpg/500px-Ca_Phe_Sua_Da.jpg', 'Photo: Clarin, CC BY 2.5, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Ca_Phe_Sua_Da.jpg', '["2 tbsp dark ground coffee", "2 tbsp condensed milk", "100 ml hot water", "Ice"]'::jsonb, '["ម្សៅកាហ្វេខ្មៅ ២ ស្លាបព្រាបាយ", "ទឹកដោះគោខាប់ ២ ស្លាបព្រាបាយ", "ទឹកក្តៅ ១០០ មីលីលីត្រ", "ទឹកកក"]'::jsonb, '["Put the condensed milk in the bottom of a heat-proof glass.", "Put the ground coffee in the phin filter, shake it level and press the filter disc on lightly.", "Pour in 2 tbsp of the hot water and wait 30 seconds so the coffee swells.", "Fill the filter with the rest of the water, cover and let it drip slowly for 4 to 5 minutes.", "Stir the coffee and milk together well.", "Pour over a glass full of ice and drink cold."]'::jsonb, '["ដាក់ទឹកដោះគោខាប់នៅបាតកែវដែលទ្រាំកម្តៅបាន។", "ដាក់ម្សៅកាហ្វេក្នុងតម្រងភីន អង្រួនឱ្យស្មើ ហើយសង្កត់បន្ទះតម្រងស្រាលៗ។", "ចាក់ទឹកក្តៅ ២ ស្លាបព្រាបាយ ហើយរង់ចាំ ៣០ វិនាទី ឱ្យកាហ្វេរីក។", "ចាក់ទឹកដែលនៅសល់ពេញតម្រង គ្រប ហើយទុកឱ្យស្រក់យឺតៗ ៤ ទៅ ៥ នាទី។", "កូរកាហ្វេ និងទឹកដោះគោឱ្យសព្វ។", "ចាក់លើកែវពេញទឹកកក ហើយផឹកត្រជាក់ៗ។"]'::jsonb),
('Larb', 'ឡាប', 'Lao minced chicken salad with lime, toasted rice and mint.', 'ញាំសាច់មាន់ចិញ្ច្រាំឡាវ ជាមួយក្រូចឆ្មា អង្ករលីង និងជីរអង្កាម។', 310, 'LA', 'salad', 25, 2, 'easy', false, 66, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/9/97/Day_224-_Chicken_Larb_%287947748382%29.jpg/500px-Day_224-_Chicken_Larb_%287947748382%29.jpg', 'Photo: Sodanie Chea from Norwalk, Ca, United States, CC BY 2.0, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Day_224-_Chicken_Larb_(7947748382).jpg', '["300 g minced chicken", "2 tbsp lime juice", "1 tbsp fish sauce", "1 tbsp toasted rice powder", "2 shallots", "Mint and cilantro"]'::jsonb, '["សាច់មាន់ចិញ្ច្រាំ ៣០០ ក្រាម", "ទឹកក្រូចឆ្មា ២ ស្លាបព្រាបាយ", "ទឹកត្រី ១ ស្លាបព្រាបាយ", "អង្ករលីងបុក ១ ស្លាបព្រាបាយ", "ខ្ទឹមក្រហម ២ មើម", "ជីរអង្កាម និងជីវ៉ាន់ស៊ុយ"]'::jsonb, '["If you have no toasted rice powder, toast 1 tbsp raw sticky rice in a dry pan until golden and grind it.", "Slice the shallots thinly and chop the mint and cilantro.", "Put the minced chicken in a pan with 3 tbsp water and cook on medium heat, breaking it up, for 5 minutes until just cooked.", "Take the pan off the heat and let it cool for 2 minutes.", "Add the lime juice, fish sauce and a pinch of sugar and mix well.", "Stir in the shallots and toasted rice powder.", "Fold in the herbs just before serving, with sticky rice and fresh vegetables."]'::jsonb, '["បើគ្មានអង្ករលីងបុក លីងអង្ករដំណើបឆៅ ១ ស្លាបព្រាបាយក្នុងខ្ទះស្ងួតរហូតលឿង ហើយបុក។", "ហាន់ខ្ទឹមក្រហមស្តើងៗ ហើយចិញ្ច្រាំជីរអង្កាម និងជីវ៉ាន់ស៊ុយ។", "ដាក់សាច់មាន់ចិញ្ច្រាំក្នុងខ្ទះជាមួយទឹក ៣ ស្លាបព្រាបាយ ចម្អិនភ្លើងមធ្យម កូរញែក ៥ នាទី រហូតទើបតែឆ្អិន។", "លើកខ្ទះចេញពីភ្លើង ហើយទុកឱ្យត្រជាក់ ២ នាទី។", "ដាក់ទឹកក្រូចឆ្មា ទឹកត្រី និងស្ករបន្តិច ហើយច្របល់ឱ្យសព្វ។", "ដាក់ខ្ទឹមក្រហម និងអង្ករលីងបុក។", "ច្របល់ជីរចូលមុនញ៉ាំ ជាមួយបាយដំណើប និងបន្លែស្រស់។"]'::jsonb),
('Tam Mak Hoong', 'បុកល្ហុងឡាវ', 'Spicy pounded green papaya salad, Lao style.', 'បុកល្ហុងហឹរ តាមរបៀបឡាវ។', 150, 'LA', 'salad', 15, 2, 'easy', false, 65, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/6/61/Lao_green_papaya_salad.jpg/500px-Lao_green_papaya_salad.jpg', 'Photo: Jpatokal, CC BY-SA 4.0, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Lao_green_papaya_salad.jpg', '["2 cups shredded green papaya", "2 chilies", "2 cloves garlic", "1 tomato", "1 tbsp fish sauce", "1 lime"]'::jsonb, '["ល្ហុងខ្ចីចិត ២ កែវ", "ម្ទេស ២ គ្រាប់", "ខ្ទឹមស ២ កំពឹស", "ប៉េងប៉ោះ ១ ផ្លែ", "ទឹកត្រី ១ ស្លាបព្រាបាយ", "ក្រូចឆ្មា ១ ផ្លែ"]'::jsonb, '["Peel the green papaya, shred it into long thin strips, rinse in cold water and drain well.", "Put the garlic and chilies in a large mortar and pound to a rough paste.", "Cut the tomato into wedges, add it and bruise it lightly with the pestle.", "Add the fish sauce, the juice of the lime and 1 tsp sugar; stir until the sugar dissolves.", "Add the papaya and pound gently while turning with a spoon, for about 1 minute, so it soaks up the dressing.", "Taste: it should be sour, salty and spicy. Adjust, then serve at once with sticky rice."]'::jsonb, '["ចិតល្ហុងខ្ចី ចិតជាសរសៃវែងស្តើង លាងទឹកត្រជាក់ ហើយស្រង់ឱ្យស្ងួត។", "ដាក់ខ្ទឹមស និងម្ទេសក្នុងត្បាល់ធំ ហើយបុកឱ្យខ្ទេច។", "កាត់ប៉េងប៉ោះជាចំណិត ដាក់ចូល ហើយបុកស្រាលៗ។", "ដាក់ទឹកត្រី ទឹកក្រូចឆ្មា និងស្ករ ១ ស្លាបព្រាកាហ្វេ កូររហូតស្កររលាយ។", "ដាក់ល្ហុង ហើយបុកថ្នមៗ ទាំងត្រឡប់ដោយស្លាបព្រា ប្រហែល ១ នាទី ឱ្យជ្រាបទឹក។", "ភ្លក់មើល៖ ជូរ ប្រៃ និងហឹរ។ កែតម្រូវ ហើយញ៉ាំភ្លាមជាមួយបាយដំណើប។"]'::jsonb),
('Mohinga', 'មហ៊ីងហ្គា', 'Burmese fish and lemongrass noodle soup, eaten for breakfast.', 'គុយទាវទឹកត្រីស្លឹកគ្រៃភូមា សម្រាប់អាហារពេលព្រឹក។', 400, 'MM', 'noodles', 60, 4, 'medium', false, 64, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/9/9b/Mohinga_bowl.jpg/500px-Mohinga_bowl.jpg', 'Photo: Junosang, CC0, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Mohinga_bowl.jpg', '["300 g catfish", "300 g thin rice noodles", "2 stalks lemongrass", "2 tbsp chickpea flour", "1 onion", "Boiled eggs and lime"]'::jsonb, '["ត្រីអណ្តែង ៣០០ ក្រាម", "មីអង្ករស្តើង ៣០០ ក្រាម", "ស្លឹកគ្រៃ ២ ដើម", "ម្សៅសណ្តែកងួរ ២ ស្លាបព្រាបាយ", "ខ្ទឹមបារាំង ១ មើម", "ស៊ុតស្ងោរ និងក្រូចឆ្មា"]'::jsonb, '["Put the catfish in a pot with 1.5 litres of water, a pinch of salt and one bruised lemongrass stalk; simmer 10 minutes.", "Lift out the fish, keep the broth, then remove skin and bones and flake the meat.", "Chop the onion and the second lemongrass stalk finely.", "Fry them in 2 tbsp oil on medium heat for 5 minutes until soft and golden.", "Add the flaked fish and stir for 2 minutes, then pour in the fish broth.", "Mix the chickpea flour with 100 ml cold water until smooth, stir it into the soup and simmer 10 minutes until slightly thick.", "Season with salt and pepper.", "Cook the noodles, divide between bowls and ladle the soup over.", "Top with halved boiled eggs and serve with lime wedges."]'::jsonb, '["ដាក់ត្រីអណ្តែងក្នុងឆ្នាំងជាមួយទឹក ១,៥ លីត្រ អំបិលបន្តិច និងស្លឹកគ្រៃមួយដើមបុកបែក ស្ងោរ ១០ នាទី។", "លើកត្រីចេញ ទុកទឹកស្ងោរ រួចបកស្បែក បេះឆ្អឹង ហើយញីសាច់។", "ចិញ្ច្រាំខ្ទឹមបារាំង និងស្លឹកគ្រៃដើមទីពីរឱ្យម៉ត់។", "លីងក្នុងប្រេង ២ ស្លាបព្រាបាយ ភ្លើងមធ្យម ៥ នាទី រហូតទន់ និងលឿង។", "ដាក់សាច់ត្រីញី កូរ ២ នាទី រួចចាក់ទឹកស្ងោរត្រី។", "លាយម្សៅសណ្តែកងួរជាមួយទឹកត្រជាក់ ១០០ មីលីលីត្រ ឱ្យម៉ត់ កូរចូលក្នុងស៊ុប ហើយរំងាស់ ១០ នាទី រហូតខាប់បន្តិច។", "ដាក់អំបិល និងម្រេច។", "ស្ងោរមី ចែកដាក់ចាន ហើយស្រោចស៊ុបពីលើ។", "ដាក់ស៊ុតស្ងោរពុះពាក់កណ្តាល ហើយញ៉ាំជាមួយក្រូចឆ្មា។"]'::jsonb),
('Lahpet Thoke', 'ញាំស្លឹកតែភូមា', 'Burmese fermented tea leaf salad with crunchy beans and nuts.', 'ញាំស្លឹកតែជ្រលក់ភូមា ជាមួយសណ្តែក និងគ្រាប់ស្រួយ។', 280, 'MM', 'salad', 15, 2, 'easy', false, 63, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c2/Fermented_Tea_Leaf_Salad.jpg/500px-Fermented_Tea_Leaf_Salad.jpg', 'Photo: Saosukham, CC0, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Fermented_Tea_Leaf_Salad.jpg', '["3 tbsp fermented tea leaves", "2 cups shredded cabbage", "1 tomato", "3 tbsp fried beans and peanuts", "1 tbsp sesame seeds", "1 lime"]'::jsonb, '["ស្លឹកតែជ្រលក់ ៣ ស្លាបព្រាបាយ", "ស្ពៃក្តោបចិត ២ កែវ", "ប៉េងប៉ោះ ១ ផ្លែ", "សណ្តែកចៀន និងសណ្តែកដី ៣ ស្លាបព្រាបាយ", "ល្ង ១ ស្លាបព្រាបាយ", "ក្រូចឆ្មា ១ ផ្លែ"]'::jsonb, '["Shred the cabbage very thinly and cut the tomato into small pieces.", "Toast the sesame seeds in a dry pan for 1 to 2 minutes until golden; let them cool.", "If the tea leaves are very wet, squeeze out a little of the liquid.", "Put the cabbage and tomato on a plate or in a bowl.", "Add the tea leaves in the middle, with the fried beans, peanuts and sesame in small piles around them.", "Just before eating, squeeze the lime over, add a pinch of salt and mix everything together at the table."]'::jsonb, '["ចិតស្ពៃក្តោបឱ្យស្តើងបំផុត ហើយកាត់ប៉េងប៉ោះជាដុំតូចៗ។", "លីងល្ងក្នុងខ្ទះស្ងួត ១ ទៅ ២ នាទី រហូតលឿង ហើយទុកឱ្យត្រជាក់។", "បើស្លឹកតែសើមពេក ច្របាច់ទឹកចេញបន្តិច។", "ដាក់ស្ពៃក្តោប និងប៉េងប៉ោះលើចាន។", "ដាក់ស្លឹកតែនៅកណ្តាល ហើយដាក់សណ្តែកចៀន សណ្តែកដី និងល្ងជាគំនរតូចៗជុំវិញ។", "មុនញ៉ាំ ច្របាច់ក្រូចឆ្មា ដាក់អំបិលបន្តិច ហើយច្របល់ទាំងអស់នៅតុ។"]'::jsonb),
('Mapo Tofu', 'តៅហ៊ូម៉ាប៉ូ', 'Sichuan tofu in a spicy, numbing chili and bean sauce with minced pork.', 'តៅហ៊ូស៊ីឈួន ក្នុងទឹកម្ទេសសណ្តែកហឹរ ជាមួយសាច់ជ្រូកចិញ្ច្រាំ។', 380, 'CN', 'main', 25, 3, 'medium', false, 62, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/7/73/Authentic_Mapo_Tofu.jpg/500px-Authentic_Mapo_Tofu.jpg', 'Photo: Sichuanfoodlover, CC BY-SA 4.0, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Authentic_Mapo_Tofu.jpg', '["400 g soft tofu", "100 g minced pork", "2 tbsp chili bean paste", "1 tsp Sichuan pepper", "2 cloves garlic", "1 tsp cornstarch"]'::jsonb, '["តៅហ៊ូទន់ ៤០០ ក្រាម", "សាច់ជ្រូកចិញ្ច្រាំ ១០០ ក្រាម", "ទឹកម្ទេសសណ្តែក ២ ស្លាបព្រាបាយ", "ម្រេចស៊ីឈួន ១ ស្លាបព្រាកាហ្វេ", "ខ្ទឹមស ២ កំពឹស", "ម្សៅពោត ១ ស្លាបព្រាកាហ្វេ"]'::jsonb, '["Cut the tofu into 2 cm cubes and soak in hot salted water for 5 minutes so it holds together; drain gently.", "Toast the Sichuan pepper in a dry pan for 1 minute, then grind it.", "Chop the garlic.", "Heat 1 tbsp oil in a wok and fry the minced pork on high heat for 3 minutes until crisp and brown.", "Turn the heat down, add the chili bean paste and garlic and fry 1 minute until the oil turns red.", "Pour in 200 ml water, add the tofu and simmer gently for 5 minutes; push the tofu instead of stirring so it does not break.", "Mix the cornstarch with 2 tbsp water, pour it in and simmer 30 seconds until glossy and thick.", "Sprinkle with the ground Sichuan pepper and serve hot with rice."]'::jsonb, '["កាត់តៅហ៊ូជាដុំការ៉េ ២ សង់ទីម៉ែត្រ ហើយត្រាំក្នុងទឹកក្តៅដាក់អំបិល ៥ នាទី ដើម្បីកុំឱ្យបែក រួចស្រង់ថ្នមៗ។", "លីងម្រេចស៊ីឈួនក្នុងខ្ទះស្ងួត ១ នាទី រួចបុក។", "ចិញ្ច្រាំខ្ទឹមស។", "កម្តៅប្រេង ១ ស្លាបព្រាបាយក្នុងខ្ទះ ហើយឆាសាច់ជ្រូកចិញ្ច្រាំលើភ្លើងខ្លាំង ៣ នាទី រហូតស្រួយ និងលឿង។", "បន្ថយភ្លើង ដាក់ទឹកម្ទេសសណ្តែក និងខ្ទឹមស លីង ១ នាទី រហូតប្រេងក្រហម។", "ចាក់ទឹក ២០០ មីលីលីត្រ ដាក់តៅហ៊ូ ហើយរំងាស់ស្រាល ៥ នាទី រុញតៅហ៊ូជំនួសការកូរ ដើម្បីកុំឱ្យបែក។", "លាយម្សៅពោតជាមួយទឹក ២ ស្លាបព្រាបាយ ចាក់ចូល ហើយរំងាស់ ៣០ វិនាទី រហូតភ្លឺខាប់។", "រោយម្រេចស៊ីឈួនបុក ហើយញ៉ាំក្តៅៗជាមួយបាយ។"]'::jsonb),
('Kung Pao Chicken', 'សាច់មាន់គុងប៉ាវ', 'Stir-fried chicken with peanuts, dried chilies and a sweet-sour sauce.', 'សាច់មាន់ឆាជាមួយសណ្តែកដី ម្ទេសក្រៀម និងទឹកជូរផ្អែម។', 450, 'CN', 'main', 25, 2, 'easy', false, 61, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a7/Kung_Pao_chicken_%28western_version%29_-1.jpg/500px-Kung_Pao_chicken_%28western_version%29_-1.jpg', 'Photo: Alexander Marks (aomarks), Public domain, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Kung_Pao_chicken_(western_version)_-1.jpg', '["300 g chicken thigh", "50 g roasted peanuts", "6 dried chilies", "2 tbsp soy sauce", "1 tbsp black vinegar", "1 tbsp sugar"]'::jsonb, '["សាច់ភ្លៅមាន់ ៣០០ ក្រាម", "សណ្តែកដីលីង ៥០ ក្រាម", "ម្ទេសក្រៀម ៦ គ្រាប់", "ទឹកស៊ីអ៊ីវ ២ ស្លាបព្រាបាយ", "ទឹកខ្មេះខ្មៅ ១ ស្លាបព្រាបាយ", "ស្ករ ១ ស្លាបព្រាបាយ"]'::jsonb, '["Cut the chicken into 2 cm cubes and mix with 1 tbsp of the soy sauce and 1 tsp oil; leave 10 minutes.", "Mix the sauce: the rest of the soy sauce, the black vinegar, the sugar and 2 tbsp water.", "Cut the dried chilies in half and shake out most of the seeds.", "Heat 2 tbsp oil in a wok on medium heat and fry the chilies for 20 seconds until dark red, without burning.", "Turn the heat to high, add the chicken and stir-fry 4 to 5 minutes until cooked through.", "Pour in the sauce and stir until it bubbles and coats the chicken.", "Add the peanuts, toss for 30 seconds and serve at once with rice."]'::jsonb, '["កាត់សាច់មាន់ជាដុំការ៉េ ២ សង់ទីម៉ែត្រ ហើយប្រឡាក់ទឹកស៊ីអ៊ីវ ១ ស្លាបព្រាបាយ និងប្រេង ១ ស្លាបព្រាកាហ្វេ ទុក ១០ នាទី។", "លាយទឹកជ្រលក់៖ ទឹកស៊ីអ៊ីវដែលនៅសល់ ទឹកខ្មេះខ្មៅ ស្ករ និងទឹក ២ ស្លាបព្រាបាយ។", "កាត់ម្ទេសក្រៀមពាក់កណ្តាល ហើយរលាស់គ្រាប់ចេញភាគច្រើន។", "កម្តៅប្រេង ២ ស្លាបព្រាបាយក្នុងខ្ទះភ្លើងមធ្យម ហើយលីងម្ទេស ២០ វិនាទី រហូតក្រហមចាស់ កុំឱ្យខ្លោច។", "បង្កើនភ្លើង ដាក់សាច់មាន់ ហើយឆា ៤ ទៅ ៥ នាទី រហូតឆ្អិនល្អ។", "ចាក់ទឹកជ្រលក់ ហើយកូររហូតពុះ និងជាប់សាច់មាន់។", "ដាក់សណ្តែកដី ច្របល់ ៣០ វិនាទី ហើយញ៉ាំភ្លាមជាមួយបាយ។"]'::jsonb),
('Oyakodon', 'បាយមាន់ស៊ុតជប៉ុន', 'Japanese rice bowl topped with chicken and soft egg simmered in sweet soy broth.', 'បាយជប៉ុន ដាក់សាច់មាន់ និងស៊ុតទន់ រំងាស់ក្នុងទឹកស៊ីអ៊ីវផ្អែម។', 620, 'JP', 'rice', 20, 2, 'easy', false, 60, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/2/29/Oyakodon_003.jpg/500px-Oyakodon_003.jpg', 'Photo: Ocdp, CC0, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Oyakodon_003.jpg', '["2 bowls cooked rice", "200 g chicken thigh", "3 eggs", "1 onion", "3 tbsp soy sauce", "1 tbsp sugar"]'::jsonb, '["បាយ ២ ចាន", "សាច់ភ្លៅមាន់ ២០០ ក្រាម", "ស៊ុត ៣ គ្រាប់", "ខ្ទឹមបារាំង ១ មើម", "ទឹកស៊ីអ៊ីវ ៣ ស្លាបព្រាបាយ", "ស្ករ ១ ស្លាបព្រាបាយ"]'::jsonb, '["Cut the chicken into bite-size pieces and slice the onion thinly.", "In a small frying pan, mix the soy sauce, sugar and 150 ml water and bring to a simmer.", "Add the onion and cook 3 minutes until soft.", "Add the chicken and simmer 5 to 6 minutes, turning once, until cooked through.", "Beat the eggs lightly, just enough to mix; streaks of white are fine.", "Pour two-thirds of the egg over the chicken, cover and cook 1 minute.", "Pour in the rest of the egg, cover and turn off the heat; leave 30 seconds so the top stays soft.", "Slide everything over bowls of hot rice, with the sauce."]'::jsonb, '["កាត់សាច់មាន់ជាដុំល្មមមាត់ ហើយហាន់ខ្ទឹមបារាំងស្តើងៗ។", "ក្នុងខ្ទះតូច លាយទឹកស៊ីអ៊ីវ ស្ករ និងទឹក ១៥០ មីលីលីត្រ ហើយដាំឱ្យពុះស្រាល។", "ដាក់ខ្ទឹមបារាំង ហើយចម្អិន ៣ នាទី រហូតទន់។", "ដាក់សាច់មាន់ រំងាស់ ៥ ទៅ ៦ នាទី ត្រឡប់ម្តង រហូតឆ្អិន។", "វាយស៊ុតស្រាលៗ គ្រាន់តែលាយ មានសសៃសខ្លះក៏បាន។", "ចាក់ស៊ុតពីរភាគបីលើសាច់មាន់ គ្រប ហើយចម្អិន ១ នាទី។", "ចាក់ស៊ុតដែលនៅសល់ គ្រប ហើយបិទភ្លើង ទុក ៣០ វិនាទី ឱ្យខាងលើនៅទន់។", "រំកិលទាំងអស់ដាក់លើបាយក្តៅ ជាមួយទឹក។"]'::jsonb),
('Miso Soup', 'ស៊ុបមីសូ', 'Light Japanese soup of miso, tofu and seaweed.', 'ស៊ុបជប៉ុនស្រាល ជាមួយមីសូ តៅហ៊ូ និងសារាយសមុទ្រ។', 90, 'JP', 'soup', 10, 2, 'easy', false, 59, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e8/Miso_Soup_001.jpg/500px-Miso_Soup_001.jpg', 'Photo: Ocdp, CC0, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Miso_Soup_001.jpg', '["500 ml dashi stock", "2 tbsp miso paste", "100 g soft tofu", "1 tbsp dried wakame", "1 spring onion"]'::jsonb, '["ទឹកស៊ុបដាស៊ី ៥០០ មីលីលីត្រ", "មីសូ ២ ស្លាបព្រាបាយ", "តៅហ៊ូទន់ ១០០ ក្រាម", "សារាយវ៉ាកាមេ ១ ស្លាបព្រាបាយ", "ស្លឹកខ្ទឹម ១ ដើម"]'::jsonb, '["Soak the dried wakame in cold water for 5 minutes, then drain.", "Cut the tofu into small cubes and slice the spring onion thinly.", "Heat the dashi in a pot until it is steaming but not boiling.", "Add the tofu and wakame and warm them for 2 minutes.", "Turn off the heat. Put the miso in a ladle, lower it into the soup and stir with chopsticks until it dissolves.", "Do not boil the soup again after adding miso, or it loses its flavour.", "Pour into bowls and top with spring onion."]'::jsonb, '["ត្រាំសារាយវ៉ាកាមេស្ងួតក្នុងទឹកត្រជាក់ ៥ នាទី រួចស្រង់។", "កាត់តៅហ៊ូជាដុំការ៉េតូចៗ ហើយហាន់ស្លឹកខ្ទឹមស្តើងៗ។", "កម្តៅទឹកដាស៊ីក្នុងឆ្នាំងរហូតហុយ ប៉ុន្តែកុំឱ្យពុះ។", "ដាក់តៅហ៊ូ និងវ៉ាកាមេ ហើយកម្តៅ ២ នាទី។", "បិទភ្លើង។ ដាក់មីសូក្នុងវែក ដាក់ចូលក្នុងស៊ុប ហើយកូរដោយចង្កឹះរហូតរលាយ។", "កុំដាំស៊ុបឱ្យពុះម្តងទៀតក្រោយដាក់មីសូ បើមិនដូច្នោះទេ រសជាតិនឹងបាត់។", "ចាក់ដាក់ចាន ហើយរោយស្លឹកខ្ទឹម។"]'::jsonb),
('Bibimbap', 'ប៊ីប៊ីមបាប', 'Korean rice bowl with seasoned vegetables, beef, egg and chili paste.', 'បាយកូរ៉េ ជាមួយបន្លែប្រឡាក់ សាច់គោ ស៊ុត និងទឹកម្ទេសកូរ៉េ។', 590, 'KR', 'rice', 40, 2, 'medium', true, 58, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/9/92/Seoul_Bibimbap_%28beef%29_-_Time_For_Kimchi.jpg/500px-Seoul_Bibimbap_%28beef%29_-_Time_For_Kimchi.jpg', 'Photo: Andy Li, CC0, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Seoul_Bibimbap_(beef)_-_Time_For_Kimchi.jpg', '["2 bowls cooked rice", "150 g beef", "1 carrot and 1 zucchini", "100 g spinach", "2 eggs", "2 tbsp gochujang"]'::jsonb, '["បាយ ២ ចាន", "សាច់គោ ១៥០ ក្រាម", "ការ៉ុត ១ និងត្រសក់បារាំង ១", "ស្ពៃខៀវ ១០០ ក្រាម", "ស៊ុត ២ គ្រាប់", "ទឹកម្ទេសកូរ៉េ ២ ស្លាបព្រាបាយ"]'::jsonb, '["Slice the beef thinly and mix with 1 tsp sugar, a pinch of salt and a little oil; leave 10 minutes.", "Cut the carrot and zucchini into thin matchsticks.", "Blanch the spinach for 30 seconds, squeeze dry and season with a pinch of salt and a few drops of oil.", "In a hot pan with a little oil, stir-fry the carrot 2 minutes, then the zucchini 2 minutes, each with a pinch of salt; keep them separate.", "Stir-fry the beef on high heat for 2 to 3 minutes until browned.", "Fry the eggs sunny side up so the yolks stay runny.", "Put hot rice in two bowls, arrange the vegetables and beef in sections on top and place an egg in the middle.", "Add the gochujang and mix everything together well before eating."]'::jsonb, '["ហាន់សាច់គោស្តើងៗ ហើយប្រឡាក់ស្ករ ១ ស្លាបព្រាកាហ្វេ អំបិលបន្តិច និងប្រេងបន្តិច ទុក ១០ នាទី។", "កាត់ការ៉ុត និងត្រសក់បារាំងជាសរសៃស្តើងៗ។", "ស្រុះស្ពៃខៀវ ៣០ វិនាទី ច្របាច់ឱ្យស្ងួត ហើយដាក់អំបិល និងប្រេងបន្តិច។", "ក្នុងខ្ទះក្តៅដាក់ប្រេងបន្តិច ឆាការ៉ុត ២ នាទី រួចត្រសក់ ២ នាទី ដាក់អំបិលបន្តិចម្តងមួយមុខ ទុកដាច់ពីគ្នា។", "ឆាសាច់គោលើភ្លើងខ្លាំង ២ ទៅ ៣ នាទី រហូតឡើងពណ៌។", "ចៀនស៊ុតពងទា ឱ្យស្នូលនៅរាវ។", "ដាក់បាយក្តៅក្នុងចានពីរ រៀបបន្លែ និងសាច់គោជាផ្នែកៗពីលើ ហើយដាក់ស៊ុតនៅកណ្តាល។", "ដាក់ទឹកម្ទេសកូរ៉េ ហើយច្របល់ឱ្យសព្វមុនញ៉ាំ។"]'::jsonb),
('Kimchi Jjigae', 'ស៊ុបគីមឈី', 'Spicy Korean kimchi stew with pork and tofu.', 'ស៊ុបគីមឈីកូរ៉េហឹរ ជាមួយសាច់ជ្រូក និងតៅហ៊ូ។', 330, 'KR', 'soup', 30, 2, 'easy', false, 57, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0c/Kimchi_jjigae_-_Kogi%2C_Brighton_2023-11-15.jpg/500px-Kimchi_jjigae_-_Kogi%2C_Brighton_2023-11-15.jpg', 'Photo: Andy Li, CC0, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Kimchi_jjigae_-_Kogi,_Brighton_2023-11-15.jpg', '["200 g aged kimchi", "150 g pork belly", "150 g tofu", "1 tbsp gochugaru", "1 spring onion", "500 ml water"]'::jsonb, '["គីមឈីចាស់ ២០០ ក្រាម", "សាច់ជ្រូកបីជាន់ ១៥០ ក្រាម", "តៅហ៊ូ ១៥០ ក្រាម", "ម្សៅម្ទេសកូរ៉េ ១ ស្លាបព្រាបាយ", "ស្លឹកខ្ទឹម ១ ដើម", "ទឹក ៥០០ មីលីលីត្រ"]'::jsonb, '["Cut the pork belly into bite-size slices and the kimchi into small pieces; keep any kimchi juice.", "Heat a pot on medium heat and fry the pork for 3 minutes until some fat melts out.", "Add the kimchi and chili flakes and stir-fry 3 to 4 minutes until the kimchi softens.", "Pour in the water and kimchi juice and bring to the boil.", "Lower the heat and simmer 15 minutes so the flavour deepens.", "Slice the tofu, lay it in the stew and simmer 5 minutes; season with salt and a pinch of sugar.", "Top with chopped spring onion and serve bubbling hot with rice."]'::jsonb, '["កាត់សាច់ជ្រូកបីជាន់ជាបន្ទះល្មមមាត់ ហើយកាត់គីមឈីជាដុំតូចៗ ទុកទឹកគីមឈី។", "កម្តៅឆ្នាំងលើភ្លើងមធ្យម ហើយលីងសាច់ជ្រូក ៣ នាទី រហូតខ្លាញ់ចេញខ្លះ។", "ដាក់គីមឈី និងម្សៅម្ទេស ហើយឆា ៣ ទៅ ៤ នាទី រហូតគីមឈីទន់។", "ចាក់ទឹក និងទឹកគីមឈី ហើយស្ងោរឱ្យពុះ។", "បន្ថយភ្លើង ហើយរំងាស់ ១៥ នាទី ឱ្យរសជាតិជ្រៅ។", "ហាន់តៅហ៊ូ ដាក់ចូល ហើយរំងាស់ ៥ នាទី ដាក់អំបិល និងស្ករបន្តិច។", "រោយស្លឹកខ្ទឹមហាន់ ហើយញ៉ាំក្តៅៗជាមួយបាយ។"]'::jsonb),
('Chana Masala', 'ការីសណ្តែកងួរ', 'North Indian chickpea curry with tomato, onion and warm spices.', 'ការីសណ្តែកងួរឥណ្ឌាខាងជើង ជាមួយប៉េងប៉ោះ ខ្ទឹមបារាំង និងគ្រឿងទេស។', 360, 'IN', 'curry', 35, 4, 'easy', false, 56, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/7/72/Chana_Masala_-_Mohammed_-_Spice_Of_Life_2024-05-27.jpg/500px-Chana_Masala_-_Mohammed_-_Spice_Of_Life_2024-05-27.jpg', 'Photo: Andy Li, CC0, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Chana_Masala_-_Mohammed_-_Spice_Of_Life_2024-05-27.jpg', '["2 cans chickpeas", "2 onions", "3 tomatoes", "1 piece ginger and 3 cloves garlic", "2 tsp garam masala", "Cilantro"]'::jsonb, '["សណ្តែកងួរ ២ កំប៉ុង", "ខ្ទឹមបារាំង ២ មើម", "ប៉េងប៉ោះ ៣ ផ្លែ", "ខ្ញី ១ ដុំ និងខ្ទឹមស ៣ កំពឹស", "ម្សៅហ្គារ៉ាម ម៉ាសាឡា ២ ស្លាបព្រាកាហ្វេ", "ជីវ៉ាន់ស៊ុយ"]'::jsonb, '["Drain and rinse the chickpeas.", "Chop the onions finely; grate the ginger and garlic; chop the tomatoes.", "Heat 3 tbsp oil in a pan and fry the onions on medium heat for 10 minutes, stirring, until deep golden.", "Add the ginger and garlic and fry 1 minute.", "Add the tomatoes, the garam masala and 1 tsp salt and cook 8 to 10 minutes until the tomatoes break down and oil shows at the edges.", "Add the chickpeas and 250 ml water, then simmer 15 minutes, mashing a few chickpeas to thicken the sauce.", "Taste for salt, sprinkle with chopped cilantro and serve with rice or flatbread."]'::jsonb, '["ស្រង់ ហើយលាងសណ្តែកងួរ។", "ចិញ្ច្រាំខ្ទឹមបារាំងឱ្យម៉ត់ កោសខ្ញី និងខ្ទឹមស ហើយកាត់ប៉េងប៉ោះ។", "កម្តៅប្រេង ៣ ស្លាបព្រាបាយក្នុងខ្ទះ ហើយលីងខ្ទឹមបារាំងភ្លើងមធ្យម ១០ នាទី កូរ រហូតលឿងចាស់។", "ដាក់ខ្ញី និងខ្ទឹមស ហើយលីង ១ នាទី។", "ដាក់ប៉េងប៉ោះ ម្សៅហ្គារ៉ាមម៉ាសាឡា និងអំបិល ១ ស្លាបព្រាកាហ្វេ ចម្អិន ៨ ទៅ ១០ នាទី រហូតប៉េងប៉ោះរលួយ និងប្រេងចេញតាមគែម។", "ដាក់សណ្តែកងួរ និងទឹក ២៥០ មីលីលីត្រ រំងាស់ ១៥ នាទី ញីសណ្តែកខ្លះឱ្យទឹកខាប់។", "ភ្លក់អំបិល រោយជីវ៉ាន់ស៊ុយហាន់ ហើយញ៉ាំជាមួយបាយ ឬនំបុ័ងសំប៉ែត។"]'::jsonb),
('Mango Lassi', 'ឡាស៊ីស្វាយ', 'Creamy Indian yogurt drink blended with ripe mango.', 'ភេសជ្ជៈយ៉ាអួឥណ្ឌា ក្រឡុកជាមួយស្វាយទុំ។', 220, 'IN', 'drinks', 5, 2, 'easy', false, 55, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5e/Mango_Lassi_and_Butter_Milk_-_Vel_South_Indian_Kitchen_%2B_Bar.jpg/500px-Mango_Lassi_and_Butter_Milk_-_Vel_South_Indian_Kitchen_%2B_Bar.jpg', 'Photo: Andy Li, CC0, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Mango_Lassi_and_Butter_Milk_-_Vel_South_Indian_Kitchen_%2B_Bar.jpg', '["1 ripe mango", "250 g plain yogurt", "100 ml milk", "1 tbsp sugar", "Ice"]'::jsonb, '["ស្វាយទុំ ១ ផ្លែ", "យ៉ាអួ ២៥០ ក្រាម", "ទឹកដោះគោ ១០០ មីលីលីត្រ", "ស្ករ ១ ស្លាបព្រាបាយ", "ទឹកកក"]'::jsonb, '["Chill the mango, yogurt and milk in the fridge for at least 1 hour.", "Peel the mango, cut the flesh off the stone and chop it.", "Put the mango, yogurt, milk and sugar in a blender.", "Blend for 1 minute until completely smooth and frothy.", "Taste and add a little more sugar if the mango is sour.", "Pour over ice and serve straight away."]'::jsonb, '["ដាក់ស្វាយ យ៉ាអួ និងទឹកដោះគោក្នុងទូទឹកកកយ៉ាងតិច ១ ម៉ោង។", "ចិតស្វាយ ឆ្វៀលសាច់ចេញពីគ្រាប់ ហើយកាត់។", "ដាក់ស្វាយ យ៉ាអួ ទឹកដោះគោ និងស្ករក្នុងម៉ាស៊ីនក្រឡុក។", "ក្រឡុក ១ នាទី រហូតម៉ត់ និងមានពពុះ។", "ភ្លក់ ហើយបន្ថែមស្ករបន្តិចបើស្វាយជូរ។", "ចាក់លើទឹកកក ហើយផឹកភ្លាម។"]'::jsonb),
('Chicken Adobo', 'សាច់មាន់អាដូបូ', 'Filipino chicken braised in vinegar, soy sauce, garlic and bay leaves.', 'សាច់មាន់ហ្វីលីពីន ខដោយទឹកខ្មេះ ទឹកស៊ីអ៊ីវ ខ្ទឹមស និងស្លឹកបេ។', 470, 'PH', 'main', 45, 4, 'easy', false, 54, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/3/38/Chicken_adobo.jpg/500px-Chicken_adobo.jpg', 'Photo: dbgg1979 on flickr, CC BY 2.0, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Chicken_adobo.jpg', '["800 g chicken pieces", "120 ml soy sauce", "80 ml vinegar", "1 head garlic", "3 bay leaves", "1 tsp black peppercorns"]'::jsonb, '["សាច់មាន់ ៨០០ ក្រាម", "ទឹកស៊ីអ៊ីវ ១២០ មីលីលីត្រ", "ទឹកខ្មេះ ៨០ មីលីលីត្រ", "ខ្ទឹមស ១ មើម", "ស្លឹកបេ ៣ សន្លឹក", "គ្រាប់ម្រេច ១ ស្លាបព្រាកាហ្វេ"]'::jsonb, '["Peel the garlic and crush the cloves lightly.", "Put the chicken, soy sauce, vinegar, garlic, bay leaves and peppercorns in a pot and mix; marinate 30 minutes.", "Add 120 ml water and bring to the boil without stirring, so the vinegar mellows.", "Cover and simmer on low heat for 30 minutes, turning the chicken once.", "Lift out the chicken and brown it in a hot pan with a little oil for 2 to 3 minutes per side.", "Meanwhile, boil the sauce uncovered for 5 to 8 minutes until it thickens and turns glossy.", "Return the chicken to the sauce, turn to coat, and serve with rice."]'::jsonb, '["បកខ្ទឹមស ហើយបុកស្រាលៗ។", "ដាក់សាច់មាន់ ទឹកស៊ីអ៊ីវ ទឹកខ្មេះ ខ្ទឹមស ស្លឹកបេ និងគ្រាប់ម្រេចក្នុងឆ្នាំង ច្របល់ ហើយប្រឡាក់ ៣០ នាទី។", "ដាក់ទឹក ១២០ មីលីលីត្រ ហើយស្ងោរឱ្យពុះដោយមិនកូរ ដើម្បីឱ្យទឹកខ្មេះស្រាល។", "គ្រប ហើយរំងាស់ភ្លើងតិច ៣០ នាទី ត្រឡប់សាច់មាន់ម្តង។", "លើកសាច់មាន់ចេញ ហើយចៀនក្នុងខ្ទះក្តៅដាក់ប្រេងបន្តិច ម្ខាង ២ ទៅ ៣ នាទី រហូតលឿង។", "ក្នុងពេលនោះ ដាំទឹកជ្រលក់ដោយមិនគ្រប ៥ ទៅ ៨ នាទី រហូតខាប់ភ្លឺ។", "ដាក់សាច់មាន់ចូលទឹកវិញ ត្រឡប់ឱ្យសព្វ ហើយញ៉ាំជាមួយបាយ។"]'::jsonb),
('Halo-Halo', 'ហាឡូហាឡូ', 'Filipino shaved ice dessert with sweet beans, fruit, milk and ube ice cream.', 'បង្អែមទឹកកកឈូសហ្វីលីពីន ជាមួយសណ្តែកផ្អែម ផ្លែឈើ ទឹកដោះគោ និងការ៉េមដំឡូងស្វាយ។', 350, 'PH', 'sweet', 15, 2, 'easy', false, 53, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/8/8d/Halo_halo_%2828049395903%29.jpg/500px-Halo_halo_%2828049395903%29.jpg', 'Photo: T.Tseng, CC BY 2.0, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Halo_halo_(28049395903).jpg', '["2 cups shaved ice", "4 tbsp sweet beans and jellies", "Ripe jackfruit or banana", "120 ml evaporated milk", "2 scoops ube ice cream"]'::jsonb, '["ទឹកកកឈូស ២ កែវ", "សណ្តែកផ្អែម និងចាហួយ ៤ ស្លាបព្រាបាយ", "ខ្នុរទុំ ឬចេក", "ទឹកដោះគោខាប់រាវ ១២០ មីលីលីត្រ", "ការ៉េមដំឡូងស្វាយ ២ ដុំ"]'::jsonb, '["Chill two tall glasses in the freezer for 10 minutes.", "Cut the jackfruit or banana into small pieces.", "Put 2 tbsp of sweet beans and jellies in the bottom of each glass, then add the fruit.", "Pack the shaved ice on top, pressing lightly so it fills the glass.", "Pour the evaporated milk slowly over the ice.", "Top each glass with a scoop of ube ice cream.", "Serve with a long spoon and mix everything together before eating."]'::jsonb, '["ដាក់កែវខ្ពស់ពីរក្នុងទូទឹកកក ១០ នាទី។", "កាត់ខ្នុរ ឬចេកជាដុំតូចៗ។", "ដាក់សណ្តែកផ្អែម និងចាហួយ ២ ស្លាបព្រាបាយនៅបាតកែវនីមួយៗ រួចដាក់ផ្លែឈើ។", "ដាក់ទឹកកកឈូសពីលើ សង្កត់ស្រាលៗឱ្យពេញកែវ។", "ចាក់ទឹកដោះគោខាប់រាវយឺតៗលើទឹកកក។", "ដាក់ការ៉េមដំឡូងស្វាយមួយដុំពីលើកែវនីមួយៗ។", "ញ៉ាំដោយស្លាបព្រាវែង ហើយកូរឱ្យសព្វមុនញ៉ាំ។"]'::jsonb),
('Nasi Goreng', 'បាយឆាឥណ្ឌូនេស៊ី', 'Indonesian sweet soy fried rice served with a fried egg.', 'បាយឆាឥណ្ឌូនេស៊ី ជាមួយទឹកស៊ីអ៊ីវផ្អែម និងស៊ុតចៀន។', 560, 'ID', 'rice', 20, 2, 'easy', false, 52, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/c/ca/Gili_Meno_Island%2C_Nasi_goreng%2C_Fried_rice_with_juice%2C_Indonesia.jpg/500px-Gili_Meno_Island%2C_Nasi_goreng%2C_Fried_rice_with_juice%2C_Indonesia.jpg', 'Photo: Vyacheslav Argenberg, CC BY 4.0, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Gili_Meno_Island,_Nasi_goreng,_Fried_rice_with_juice,_Indonesia.jpg', '["2 cups day-old rice", "2 shallots and 2 cloves garlic", "1 chili", "2 tbsp kecap manis (sweet soy)", "2 eggs", "Cucumber and crackers"]'::jsonb, '["បាយសល់ពីម្សិលមិញ ២ កែវ", "ខ្ទឹមក្រហម ២ និងខ្ទឹមស ២ កំពឹស", "ម្ទេស ១ គ្រាប់", "ទឹកស៊ីអ៊ីវផ្អែម ២ ស្លាបព្រាបាយ", "ស៊ុត ២ គ្រាប់", "ត្រសក់ និងនំក្រៀប"]'::jsonb, '["Break up the cold rice with your fingers so there are no lumps.", "Pound or finely chop the shallots, garlic and chili into a paste.", "Heat 2 tbsp oil in a wok on medium heat and fry the paste for 1 to 2 minutes until fragrant.", "Turn the heat to high, add the rice and stir-fry 3 minutes until hot.", "Add the sweet soy sauce and a pinch of salt and toss until every grain is evenly brown.", "In another pan, fry the eggs in a little oil until the edges are crisp.", "Serve the rice topped with a fried egg, with cucumber slices and crackers on the side."]'::jsonb, '["ញែកបាយត្រជាក់ដោយដៃ ដើម្បីកុំឱ្យមានដុំ។", "បុក ឬចិញ្ច្រាំខ្ទឹមក្រហម ខ្ទឹមស និងម្ទេសឱ្យម៉ត់។", "កម្តៅប្រេង ២ ស្លាបព្រាបាយក្នុងខ្ទះភ្លើងមធ្យម ហើយលីងគ្រឿង ១ ទៅ ២ នាទី រហូតឈ្ងុយ។", "បង្កើនភ្លើង ដាក់បាយ ហើយឆា ៣ នាទី រហូតក្តៅ។", "ដាក់ទឹកស៊ីអ៊ីវផ្អែម និងអំបិលបន្តិច ហើយឆារហូតបាយមានពណ៌ស្មើគ្នា។", "ក្នុងខ្ទះមួយទៀត ចៀនស៊ុតក្នុងប្រេងបន្តិច រហូតគែមស្រួយ។", "ដាក់បាយ ហើយដាក់ស៊ុតចៀនពីលើ ជាមួយត្រសក់ និងនំក្រៀប។"]'::jsonb),
('Gado-Gado', 'ហ្គាដូហ្គាដូ', 'Indonesian vegetable salad with egg, tofu and a peanut sauce.', 'ញាំបន្លែឥណ្ឌូនេស៊ី ជាមួយស៊ុត តៅហ៊ូ និងទឹកជ្រលក់សណ្តែកដី។', 420, 'ID', 'salad', 30, 2, 'easy', false, 51, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/6/65/Gado-gado_-_Bali_2025-09-25.jpg/500px-Gado-gado_-_Bali_2025-09-25.jpg', 'Photo: Andy Li, CC0, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Gado-gado_-_Bali_2025-09-25.jpg', '["Cabbage, green beans and bean sprouts", "1 potato", "2 boiled eggs", "100 g fried tofu", "4 tbsp peanut sauce", "Prawn crackers"]'::jsonb, '["ស្ពៃក្តោប សណ្តែកកួរ និងសណ្តែកបណ្តុះ", "ដំឡូងបារាំង ១ មើម", "ស៊ុតស្ងោរ ២ គ្រាប់", "តៅហ៊ូចៀន ១០០ ក្រាម", "ទឹកជ្រលក់សណ្តែកដី ៤ ស្លាបព្រាបាយ", "នំក្រៀបបង្គា"]'::jsonb, '["Boil the potato in salted water for 15 minutes until tender, then cool and slice.", "Boil the eggs for 9 minutes, cool in cold water, peel and cut into quarters.", "Blanch the green beans for 3 minutes, the cabbage for 1 minute and the bean sprouts for 20 seconds; drain.", "Cut the fried tofu into cubes.", "Warm the peanut sauce with 2 to 3 tbsp water until it pours easily.", "Arrange the vegetables, potato, egg and tofu on a plate.", "Pour the warm peanut sauce over and serve with prawn crackers."]'::jsonb, '["ស្ងោរដំឡូងក្នុងទឹកអំបិល ១៥ នាទី រហូតទន់ ទុកឱ្យត្រជាក់ ហើយហាន់។", "ស្ងោរស៊ុត ៩ នាទី ត្រាំទឹកត្រជាក់ បក ហើយកាត់ជាបួន។", "ស្រុះសណ្តែកកួរ ៣ នាទី ស្ពៃក្តោប ១ នាទី និងសណ្តែកបណ្តុះ ២០ វិនាទី ហើយស្រង់។", "កាត់តៅហ៊ូចៀនជាដុំការ៉េ។", "កម្តៅទឹកជ្រលក់សណ្តែកដីជាមួយទឹក ២ ទៅ ៣ ស្លាបព្រាបាយ រហូតរាវល្មម។", "រៀបបន្លែ ដំឡូង ស៊ុត និងតៅហ៊ូលើចាន។", "ស្រោចទឹកជ្រលក់សណ្តែកដីឧណ្ហៗពីលើ ហើយញ៉ាំជាមួយនំក្រៀបបង្គា។"]'::jsonb),
('Nasi Lemak', 'បាយខ្ទិះដូងម៉ាឡេ', 'Malaysian coconut rice with sambal, egg, peanuts and crispy anchovies.', 'បាយខ្ទិះដូងម៉ាឡេស៊ី ជាមួយសាំបាល់ ស៊ុត សណ្តែកដី និងត្រីឆ្អើរស្រួយ។', 640, 'MY', 'rice', 45, 2, 'medium', false, 50, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d4/Nasi_Lemak_-_Roti_King_2025-09-19.jpg/500px-Nasi_Lemak_-_Roti_King_2025-09-19.jpg', 'Photo: Andy Li, CC0, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Nasi_Lemak_-_Roti_King_2025-09-19.jpg', '["1 cup rice", "200 ml coconut milk", "1 pandan leaf", "3 tbsp sambal", "2 boiled eggs", "Fried anchovies, peanuts and cucumber"]'::jsonb, '["អង្ករ ១ កែវ", "ខ្ទិះដូង ២០០ មីលីលីត្រ", "ស្លឹកតើយ ១ សន្លឹក", "សាំបាល់ ៣ ស្លាបព្រាបាយ", "ស៊ុតស្ងោរ ២ គ្រាប់", "ត្រីឆ្អើរចៀន សណ្តែកដី និងត្រសក់"]'::jsonb, '["Wash the rice until the water runs clear and drain.", "Put the rice in a pot with the coconut milk, 150 ml water, a pinch of salt and the knotted pandan leaf.", "Bring to the boil, then cover and cook on the lowest heat for 15 minutes; rest 10 minutes without lifting the lid.", "Boil the eggs for 9 minutes, cool, peel and halve.", "Fry the anchovies in oil on medium heat for 2 to 3 minutes until crisp, then the peanuts for 2 minutes; drain on paper.", "Slice the cucumber.", "Warm the sambal in a small pan.", "Fluff the rice and serve it with the sambal, egg, anchovies, peanuts and cucumber around it."]'::jsonb, '["លាងអង្កររហូតទឹកថ្លា ហើយស្រង់។", "ដាក់អង្ករក្នុងឆ្នាំងជាមួយខ្ទិះដូង ទឹក ១៥០ មីលីលីត្រ អំបិលបន្តិច និងស្លឹកតើយចងជាថ្នាំង។", "ដាំឱ្យពុះ រួចគ្រប ហើយចម្អិនភ្លើងតិចបំផុត ១៥ នាទី ហើយទុក ១០ នាទីដោយមិនបើកគម្រប។", "ស្ងោរស៊ុត ៩ នាទី ទុកឱ្យត្រជាក់ បក ហើយពុះពាក់កណ្តាល។", "ចៀនត្រីឆ្អើរក្នុងប្រេងភ្លើងមធ្យម ២ ទៅ ៣ នាទី រហូតស្រួយ រួចចៀនសណ្តែកដី ២ នាទី ហើយស្រង់លើក្រដាស។", "ហាន់ត្រសក់។", "កម្តៅសាំបាល់ក្នុងខ្ទះតូច។", "កាយបាយឱ្យរលុង ហើយញ៉ាំជាមួយសាំបាល់ ស៊ុត ត្រីឆ្អើរ សណ្តែកដី និងត្រសក់ជុំវិញ។"]'::jsonb),
('Teh Tarik', 'តែទាញ', 'Frothy Malaysian milk tea, poured back and forth to cool and foam.', 'តែទឹកដោះគោម៉ាឡេស៊ីមានពពុះ ចាក់ទាញទៅមកឱ្យពពុះ។', 160, 'MY', 'drinks', 10, 2, 'easy', false, 49, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d8/Roti_Telur_and_Teh_Tarik.jpg/500px-Roti_Telur_and_Teh_Tarik.jpg', 'Photo: Azreey, CC BY-SA 4.0, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Roti_Telur_and_Teh_Tarik.jpg', '["2 tbsp black tea leaves", "400 ml boiling water", "3 tbsp condensed milk", "2 tbsp evaporated milk"]'::jsonb, '["ស្លឹកតែខ្មៅ ២ ស្លាបព្រាបាយ", "ទឹកពុះ ៤០០ មីលីលីត្រ", "ទឹកដោះគោខាប់ ៣ ស្លាបព្រាបាយ", "ទឹកដោះគោខាប់រាវ ២ ស្លាបព្រាបាយ"]'::jsonb, '["Bring the water to a full boil.", "Add the tea leaves, turn off the heat and let them brew for 5 minutes until very strong.", "Strain the tea into a jug.", "Stir in the condensed milk and evaporated milk until dissolved.", "Pour the tea from the jug into a second jug from as high as you safely can, then pour it back; repeat 5 or 6 times.", "When there is a thick layer of foam on top, pour into cups and serve hot."]'::jsonb, '["ដាំទឹកឱ្យពុះខ្លាំង។", "ដាក់ស្លឹកតែ បិទភ្លើង ហើយទុក ៥ នាទី រហូតតែខ្លាំង។", "ចម្រោះតែដាក់ក្នុងប៉ាន់។", "ដាក់ទឹកដោះគោខាប់ និងទឹកដោះគោខាប់រាវ ហើយកូររហូតរលាយ។", "ចាក់តែពីប៉ាន់មួយទៅប៉ាន់មួយទៀតពីខ្ពស់តាមដែលអាចធ្វើបានដោយសុវត្ថិភាព រួចចាក់ត្រឡប់វិញ ធ្វើ ៥ ឬ ៦ ដង។", "ពេលមានពពុះក្រាស់ពីលើ ចាក់ដាក់ពែង ហើយញ៉ាំក្តៅៗ។"]'::jsonb),
('Hainanese Chicken Rice', 'បាយមាន់ហៃណាន', 'Poached chicken with fragrant ginger rice and chili sauce.', 'សាច់មាន់ស្ងោរ ជាមួយបាយខ្ញីក្រអូប និងទឹកម្ទេស។', 600, 'SG', 'rice', 60, 4, 'medium', false, 48, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/7/71/Hainanese_Chicken_Rice.jpg/500px-Hainanese_Chicken_Rice.jpg', 'Photo: No machine-readable author provided. Terence assumed (based on copyright claims), CC BY 2.5, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Hainanese_Chicken_Rice.jpg', '["1 whole chicken", "2 cups rice", "1 large piece ginger", "4 cloves garlic", "Chili sauce", "Cucumber"]'::jsonb, '["មាន់ ១ ក្បាល", "អង្ករ ២ កែវ", "ខ្ញី ១ ដុំធំ", "ខ្ទឹមស ៤ កំពឹស", "ទឹកម្ទេស", "ត្រសក់"]'::jsonb, '["Rub the chicken all over with salt, rinse it and pat dry.", "Put half the ginger, sliced, inside the chicken and place it in a pot of water that just covers it.", "Bring to a gentle boil, then turn the heat to the lowest and poach 35 to 40 minutes, without boiling, until the juices run clear.", "Lift the chicken into a bowl of ice water for 10 minutes so the skin turns firm and smooth. Keep the broth.", "Wash the rice and drain. Chop the garlic and the rest of the ginger.", "Fry the garlic and ginger in 2 tbsp oil for 1 minute, add the rice and stir 2 minutes until shiny.", "Cook the rice with chicken broth instead of water (same amount as usual) and a pinch of salt.", "Cut the chicken into pieces and serve with the rice, cucumber slices, chili sauce and a bowl of hot broth."]'::jsonb, '["ដុសអំបិលលើមាន់ទាំងមូល លាង ហើយជូតឱ្យស្ងួត។", "ដាក់ខ្ញីពាក់កណ្តាលហាន់ក្នុងពោះមាន់ ហើយដាក់មាន់ក្នុងឆ្នាំងទឹកល្មមលិច។", "ដាំឱ្យពុះស្រាល រួចបន្ថយភ្លើងតិចបំផុត ហើយស្ងោរ ៣៥ ទៅ ៤០ នាទី កុំឱ្យពុះ រហូតទឹកសាច់ថ្លា។", "លើកមាន់ដាក់ក្នុងទឹកកក ១០ នាទី ឱ្យស្បែករឹង និងរលោង។ ទុកទឹកស៊ុប។", "លាងអង្ករ ហើយស្រង់។ ចិញ្ច្រាំខ្ទឹមស និងខ្ញីដែលនៅសល់។", "លីងខ្ទឹមស និងខ្ញីក្នុងប្រេង ២ ស្លាបព្រាបាយ ១ នាទី ដាក់អង្ករ ហើយកូរ ២ នាទី រហូតភ្លឺ។", "ដាំបាយដោយប្រើទឹកស៊ុបមាន់ជំនួសទឹក (បរិមាណដូចធម្មតា) និងអំបិលបន្តិច។", "កាត់មាន់ជាដុំ ហើយញ៉ាំជាមួយបាយ ត្រសក់ ទឹកម្ទេស និងទឹកស៊ុបក្តៅមួយចាន។"]'::jsonb),
('Kaya Toast', 'នំបុ័ងអាំងកាយ៉ា', 'Crisp toast with coconut-egg jam and butter, a Singapore breakfast.', 'នំបុ័ងអាំងស្រួយ ជាមួយយៈសាពូងស៊ុតដូង និងប៊ឺ ជាអាហារពេលព្រឹកសិង្ហបុរី។', 340, 'SG', 'snack', 10, 1, 'easy', false, 47, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/a/ad/Kaya_Toast_with_Coffee_%28cropped%29.jpg/500px-Kaya_Toast_with_Coffee_%28cropped%29.jpg', 'Photo: Daniel., CC BY 2.0, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Kaya_Toast_with_Coffee_(cropped).jpg', '["2 slices white bread", "2 tbsp kaya jam", "1 tbsp cold butter", "2 soft-boiled eggs", "Soy sauce and pepper"]'::jsonb, '["នំបុ័ងស ២ ចំណិត", "យៈសាពូកាយ៉ា ២ ស្លាបព្រាបាយ", "ប៊ឺត្រជាក់ ១ ស្លាបព្រាបាយ", "ស៊ុតស្ងោរទន់ ២ គ្រាប់", "ទឹកស៊ីអ៊ីវ និងម្រេច"]'::jsonb, '["Put the eggs in a bowl and cover with boiling water; leave 6 to 7 minutes for soft eggs.", "Toast the bread until golden and crisp; trim off the crusts if you like.", "Slice the cold butter as thinly as you can.", "Spread a thick layer of kaya on one slice of toast.", "Lay the butter slices on top and close with the second slice; cut in half.", "Crack the soft eggs into a small bowl and season with a few drops of soy sauce and pepper.", "Eat the toast while the butter is still cold, dipping it into the eggs."]'::jsonb, '["ដាក់ស៊ុតក្នុងចាន ហើយចាក់ទឹកពុះឱ្យលិច ទុក ៦ ទៅ ៧ នាទី សម្រាប់ស៊ុតទន់។", "អាំងនំបុ័ងរហូតលឿងស្រួយ កាត់គែមចេញបើចង់។", "ហាន់ប៊ឺត្រជាក់ឱ្យស្តើងបំផុត។", "លាបកាយ៉ាក្រាស់លើនំបុ័ងមួយចំណិត។", "ដាក់ប៊ឺពីលើ ហើយគ្របដោយនំបុ័ងមួយទៀត កាត់ពាក់កណ្តាល។", "វាយស៊ុតទន់ចូលក្នុងចានតូច ហើយដាក់ទឹកស៊ីអ៊ីវពីរបីដំណក់ និងម្រេច។", "ញ៉ាំនំបុ័ងពេលប៊ឺនៅត្រជាក់ ដោយជ្រលក់ក្នុងស៊ុត។"]'::jsonb),
('Fish Amok', 'អាម៉ុកត្រី', 'Soft coconut fish curry steamed in banana leaf cups.', 'ការីត្រីខ្ទិះដូងទន់ៗ ចំហុយក្នុងស្លឹកចេក។', 420, 'KH', 'curry', 45, 4, 'medium', true, 100, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/2/2c/Fish_Amok_with_Rice.jpg/500px-Fish_Amok_with_Rice.jpg', 'Photo: sharonang, CC0, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Fish_Amok_with_Rice.jpg', '["500 g white fish fillet", "200 ml coconut milk", "2 tbsp kroeung paste", "1 egg", "1 tbsp fish sauce", "Banana leaves"]'::jsonb, '["សាច់ត្រីស ៥០០ ក្រាម", "ខ្ទិះដូង ២០០ មីលីលីត្រ", "គ្រឿង ២ ស្លាបព្រាបាយ", "ស៊ុត ១ គ្រាប់", "ទឹកត្រី ១ ស្លាបព្រាបាយ", "ស្លឹកចេក"]'::jsonb, '["Cut the fish into thin bite-size slices, sprinkle with a pinch of salt and set aside.", "Soften the banana leaves over a low flame or in hot water for a few seconds so they fold without tearing.", "Make 4 cups: put two leaf circles together, fold up the sides into a square bowl and pin the corners with toothpicks.", "In a bowl, whisk the kroeung paste with 150 ml of the coconut milk until smooth.", "Beat in the egg and fish sauce with a pinch of sugar, then gently fold in the fish.", "Spoon the mixture into the leaf cups, filling each about three-quarters full.", "Steam over boiling water with the lid on for 20 to 25 minutes, until the curry is set like a soft custard.", "Spoon the rest of the coconut milk on top and steam 2 more minutes. Serve hot with steamed rice."]'::jsonb, '["កាត់ត្រីជាចំណិតស្តើងៗ រោយអំបិលបន្តិច ហើយទុកមួយឡែក។", "អាំងស្លឹកចេកលើភ្លើងតិចៗ ឬជ្រលក់ទឹកក្តៅពីរបីវិនាទី ដើម្បីឱ្យទន់ងាយបត់មិនរហែក។", "ធ្វើកន្ទោង ៤៖ ដាក់ស្លឹកមូលពីរជាន់ បត់គែមឡើងជារាងចានការ៉េ ហើយដោតជ្រុងដោយចង្កឹះ។", "ក្នុងចាន វាយគ្រឿងជាមួយខ្ទិះដូង ១៥០ មីលីលីត្រ ឱ្យម៉ត់។", "វាយស៊ុត ទឹកត្រី និងស្ករបន្តិចចូល រួចច្របល់ត្រីចូលថ្នមៗ។", "ដួសល្បាយដាក់ក្នុងកន្ទោងស្លឹកចេក ប្រហែលបីភាគបួន។", "ចំហុយលើទឹកពុះ គម្របជិត ២០ ទៅ ២៥ នាទី រហូតដល់ការីស្អិតដូចសង់ខ្យាទន់។", "ដួសខ្ទិះដូងដែលនៅសល់ដាក់ពីលើ ហើយចំហុយ ២ នាទីទៀត។ ញ៉ាំក្តៅៗជាមួយបាយ។"]'::jsonb),
('Lok Lak', 'ឡុកឡាក់', 'Peppered stir-fried beef with a lime and black pepper dip.', 'សាច់គោឆាម្រេច ជាមួយទឹកជ្រលក់ក្រូចឆ្មាម្រេច។', 510, 'KH', 'main', 30, 2, 'easy', false, 98, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e2/Sachko_lok_lak_-_beef_lok_lak_th%E1%BB%8Bt_b%C3%B2_l%C3%BAc_l%E1%BA%AFc_Khmer_food.jpg/500px-Sachko_lok_lak_-_beef_lok_lak_th%E1%BB%8Bt_b%C3%B2_l%C3%BAc_l%E1%BA%AFc_Khmer_food.jpg', 'Photo: Alexandersingh9, CC0, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Sachko_lok_lak_-_beef_lok_lak_th%E1%BB%8Bt_b%C3%B2_l%C3%BAc_l%E1%BA%AFc_Khmer_food.jpg', '["300 g beef sirloin", "2 tbsp soy sauce", "1 tbsp oyster sauce", "3 cloves garlic", "Lettuce, tomato and onion", "1 lime and black pepper"]'::jsonb, '["សាច់គោ ៣០០ ក្រាម", "ទឹកស៊ីអ៊ីវ ២ ស្លាបព្រាបាយ", "ប្រេងខ្យង ១ ស្លាបព្រាបាយ", "ខ្ទឹមស ៣ កំពឹស", "សាឡាត់ ប៉េងប៉ោះ និងខ្ទឹមបារាំង", "ក្រូចឆ្មា ១ ផ្លែ និងម្រេចខ្មៅ"]'::jsonb, '["Cut the beef into 2 cm cubes and pat dry with paper towel.", "Crush the garlic and mix with the soy sauce, oyster sauce, 1 tsp sugar and a little black pepper.", "Coat the beef in the marinade and leave for 15 to 30 minutes.", "Make the dip: mix the juice of the lime with 1 tsp black pepper and a pinch of salt.", "Slice the tomato and onion and arrange on a plate with the lettuce leaves.", "Heat 1 tbsp oil in a wok until it just starts to smoke.", "Add the beef in one layer and sear for 1 minute without moving, then stir-fry 1 to 2 minutes until browned but still juicy.", "Pile the beef on the vegetables and serve at once with rice and the lime-pepper dip."]'::jsonb, '["កាត់សាច់គោជាដុំការ៉េ ២ សង់ទីម៉ែត្រ ហើយជូតឱ្យស្ងួតដោយក្រដាស។", "ចិញ្ច្រាំខ្ទឹមស ហើយលាយជាមួយទឹកស៊ីអ៊ីវ ប្រេងខ្យង ស្ករ ១ ស្លាបព្រាកាហ្វេ និងម្រេចបន្តិច។", "ប្រឡាក់សាច់គោក្នុងគ្រឿង ហើយទុក ១៥ ទៅ ៣០ នាទី។", "ធ្វើទឹកជ្រលក់៖ លាយទឹកក្រូចឆ្មាជាមួយម្រេចខ្មៅ ១ ស្លាបព្រាកាហ្វេ និងអំបិលបន្តិច។", "ហាន់ប៉េងប៉ោះ និងខ្ទឹមបារាំង ហើយរៀបលើចានជាមួយស្លឹកសាឡាត់។", "កម្តៅប្រេង ១ ស្លាបព្រាបាយក្នុងខ្ទះ រហូតចាប់ផ្តើមហុយ។", "ដាក់សាច់គោឱ្យរាលមួយជាន់ ទុក ១ នាទីកុំកូរ រួចឆា ១ ទៅ ២ នាទី រហូតឡើងពណ៌ ប៉ុន្តែនៅមានទឹក។", "ដាក់សាច់គោលើបន្លែ ហើយញ៉ាំភ្លាមជាមួយបាយ និងទឹកជ្រលក់ក្រូចឆ្មាម្រេច។"]'::jsonb),
('Nom Banh Chok', 'នំបញ្ចុក', 'Fresh rice noodles in a green fish gravy with herbs and vegetables.', 'នំបញ្ចុកស្រស់ ជាមួយសម្លប្រហើរត្រី និងបន្លែស្រស់។', 380, 'KH', 'noodles', 60, 4, 'hard', false, 96, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/c/cb/Num_Banh_Chok_%28cropped%29.jpg/500px-Num_Banh_Chok_%28cropped%29.jpg', 'Photo: Thomas Wanhoff from Siem Reap, Cambodia, CC BY-SA 2.0, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Num_Banh_Chok_(cropped).jpg', '["500 g fresh rice noodles", "300 g fish", "Lemongrass, turmeric and galangal", "200 ml coconut milk", "Banana flower, cucumber and herbs"]'::jsonb, '["នំបញ្ចុកស្រស់ ៥០០ ក្រាម", "ត្រី ៣០០ ក្រាម", "ស្លឹកគ្រៃ រមៀត និងរំដេង", "ខ្ទិះដូង ២០០ មីលីលីត្រ", "ត្រយូងចេក ត្រសក់ និងជីរ"]'::jsonb, '["Put the fish in a pot with 1 litre of water and a pinch of salt, boil 10 minutes, then lift out the fish and keep the water.", "When cool, remove skin and bones and flake the fish finely.", "Slice the lemongrass, turmeric and galangal thinly and pound them in a mortar to a smooth yellow paste.", "Fry the paste in 1 tbsp oil over medium heat for 2 minutes until fragrant.", "Add the flaked fish and stir for 2 minutes, mashing it into the paste.", "Pour in the fish water and coconut milk, season with salt and a pinch of sugar, and simmer gently for 20 minutes.", "Slice the banana flower and cucumber thinly and wash the herbs.", "Rinse the noodles in cold water, put a handful in each bowl and ladle the hot gravy over.", "Top with the fresh vegetables and herbs and serve."]'::jsonb, '["ដាក់ត្រីក្នុងឆ្នាំងជាមួយទឹក ១ លីត្រ និងអំបិលបន្តិច ស្ងោរ ១០ នាទី រួចលើកត្រីចេញ ហើយទុកទឹកស្ងោរ។", "ពេលត្រជាក់ បកស្បែក និងបេះឆ្អឹងចេញ ហើយញីសាច់ត្រីឱ្យម៉ត់។", "ហាន់ស្លឹកគ្រៃ រមៀត និងរំដេងឱ្យស្តើង ហើយបុកក្នុងត្បាល់ឱ្យម៉ត់ពណ៌លឿង។", "លីងគ្រឿងក្នុងប្រេង ១ ស្លាបព្រាបាយ លើភ្លើងមធ្យម ២ នាទី រហូតឈ្ងុយ។", "ដាក់សាច់ត្រីញី ហើយកូរ ២ នាទី ញីឱ្យសព្វជាមួយគ្រឿង។", "ចាក់ទឹកស្ងោរត្រី និងខ្ទិះដូង ដាក់អំបិល និងស្ករបន្តិច ហើយរំងាស់ភ្លើងតិច ២០ នាទី។", "ហាន់ត្រយូងចេក និងត្រសក់ឱ្យស្តើង ហើយលាងជីរ។", "លាងនំបញ្ចុកក្នុងទឹកត្រជាក់ ដាក់មួយក្តាប់ក្នុងចាននីមួយៗ ហើយស្រោចសម្លក្តៅពីលើ។", "ដាក់បន្លែស្រស់ និងជីរពីលើ ហើយញ៉ាំ។"]'::jsonb),
('Kuy Teav', 'គុយទាវ', 'Pork noodle soup with a clear, light broth.', 'គុយទាវសាច់ជ្រូក ជាមួយទឹកស៊ុបថ្លាស្រាល។', 350, 'KH', 'noodles', 40, 2, 'easy', false, 94, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/b/bf/H%E1%BB%A7_ti%E1%BA%BFu_Nam_Vang_gi%C3%B2_2.jpg/500px-H%E1%BB%A7_ti%E1%BA%BFu_Nam_Vang_gi%C3%B2_2.jpg', 'Photo: Phương Huy (thảo luận), Public domain, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:H%E1%BB%A7_ti%E1%BA%BFu_Nam_Vang_gi%C3%B2_2.jpg', '["200 g rice noodles", "200 g pork", "500 g pork bones", "1 tbsp garlic oil", "Bean sprouts and spring onion"]'::jsonb, '["គុយទាវ ២០០ ក្រាម", "សាច់ជ្រូក ២០០ ក្រាម", "ឆ្អឹងជ្រូក ៥០០ ក្រាម", "ប្រេងខ្ទឹម ១ ស្លាបព្រាបាយ", "សណ្តែកបណ្តុះ និងស្លឹកខ្ទឹម"]'::jsonb, '["Rinse the pork bones, cover with cold water, bring to the boil for 5 minutes, then drain and rinse to remove the scum.", "Put the clean bones in a pot with 2 litres of water, bring to the boil, then simmer uncovered on low heat for 1 hour.", "Add the pork to the broth for the last 20 minutes, then lift it out, cool and slice thinly.", "Season the broth with salt and 1 tsp sugar; keep it at a gentle simmer.", "Soak the rice noodles in warm water for 10 minutes until soft, then drain.", "Blanch a portion of noodles and bean sprouts in boiling water for 20 seconds and drain well into a bowl.", "Top with the sliced pork and a little garlic oil.", "Ladle the hot broth over, sprinkle with chopped spring onion and pepper, and serve straight away."]'::jsonb, '["លាងឆ្អឹងជ្រូក ដាក់ទឹកត្រជាក់ឱ្យលិច ស្ងោរឱ្យពុះ ៥ នាទី រួចចាក់ចោល ហើយលាងឱ្យស្អាត។", "ដាក់ឆ្អឹងស្អាតក្នុងឆ្នាំងជាមួយទឹក ២ លីត្រ ស្ងោរឱ្យពុះ រួចរំងាស់ភ្លើងតិចមួយម៉ោង ដោយមិនគ្រប។", "ដាក់សាច់ជ្រូកក្នុងទឹកស៊ុប ២០ នាទីចុងក្រោយ រួចលើកចេញ ទុកឱ្យត្រជាក់ ហើយហាន់ស្តើងៗ។", "ដាក់អំបិល និងស្ករ ១ ស្លាបព្រាកាហ្វេក្នុងទឹកស៊ុប ហើយទុកឱ្យពុះស្រាលៗ។", "ត្រាំគុយទាវក្នុងទឹកឧណ្ហៗ ១០ នាទី រហូតទន់ រួចស្រង់។", "ស្រុះគុយទាវ និងសណ្តែកបណ្តុះមួយចំណែកក្នុងទឹកពុះ ២០ វិនាទី ហើយស្រង់ដាក់ចាន។", "ដាក់សាច់ជ្រូកហាន់ និងប្រេងខ្ទឹមបន្តិចពីលើ។", "ស្រោចទឹកស៊ុបក្តៅ រោយស្លឹកខ្ទឹមហាន់ និងម្រេច ហើយញ៉ាំភ្លាម។"]'::jsonb),
('Bai Sach Chrouk', 'បាយសាច់ជ្រូក', 'Grilled coconut-garlic pork over broken rice with pickles.', 'សាច់ជ្រូកអាំងខ្ទិះដូងខ្ទឹម លើបាយ ជាមួយជ្រក់។', 560, 'KH', 'rice', 30, 2, 'easy', false, 92, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/1/15/Bay_sach_chrouk.jpg/500px-Bay_sach_chrouk.jpg', 'Photo: Mingjang Teang, CC BY-SA 4.0, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Bay_sach_chrouk.jpg', '["300 g pork slices", "3 tbsp coconut milk", "3 cloves garlic", "1 tbsp fish sauce", "1 tbsp sugar", "2 cups cooked rice", "Pickled vegetables"]'::jsonb, '["សាច់ជ្រូកហាន់ ៣០០ ក្រាម", "ខ្ទិះដូង ៣ ស្លាបព្រាបាយ", "ខ្ទឹមស ៣ កំពឹស", "ទឹកត្រី ១ ស្លាបព្រាបាយ", "ស្ករ ១ ស្លាបព្រាបាយ", "បាយ ២ កែវ", "ជ្រក់បន្លែ"]'::jsonb, '["Slice the pork thinly against the grain, about 5 mm thick.", "Crush the garlic and mix with the coconut milk, fish sauce, sugar and a little pepper.", "Coat the pork well and marinate for at least 1 hour, or overnight in the fridge.", "Heat a grill, griddle pan or charcoal grill until very hot.", "Grill the pork 2 to 3 minutes per side, brushing with leftover marinade, until cooked through and charred at the edges.", "Rest the pork for 2 minutes, then slice into strips.", "Serve the pork over warm rice with the pickled vegetables on the side."]'::jsonb, '["ហាន់សាច់ជ្រូកឱ្យស្តើងប្រហែល ៥ មីលីម៉ែត្រ កាត់ឆ្លងសរសៃសាច់។", "ចិញ្ច្រាំខ្ទឹមស ហើយលាយជាមួយខ្ទិះដូង ទឹកត្រី ស្ករ និងម្រេចបន្តិច។", "ប្រឡាក់សាច់ជ្រូកឱ្យសព្វ ហើយទុកយ៉ាងតិច ១ ម៉ោង ឬមួយយប់ក្នុងទូទឹកកក។", "កម្តៅចង្ក្រានអាំង ខ្ទះអាំង ឬធ្យូងឱ្យក្តៅខ្លាំង។", "អាំងសាច់ម្ខាង ២ ទៅ ៣ នាទី លាបគ្រឿងសល់ រហូតឆ្អិន និងឆេះគែមបន្តិច។", "ទុកសាច់ ២ នាទី រួចហាន់ជាបន្ទះ។", "ដាក់សាច់លើបាយក្តៅ ហើយញ៉ាំជាមួយជ្រក់បន្លែ។"]'::jsonb),
('Samlor Machu Trey', 'សម្លម្ជូរត្រី', 'Sour fish soup with pineapple and tamarind.', 'សម្លម្ជូរត្រី ជាមួយម្នាស់ និងអំពិល។', 250, 'KH', 'soup', 35, 4, 'easy', false, 90, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/2/21/Samlar_Machu_%287947801760%29.jpg/500px-Samlar_Machu_%287947801760%29.jpg', 'Photo: Sodanie Chea from Norwalk, Ca, United States, CC BY 2.0, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Samlar_Machu_(7947801760).jpg', '["400 g fish", "2 tbsp tamarind paste", "1 cup pineapple pieces", "2 tomatoes", "Morning glory or herbs", "1 tbsp fish sauce"]'::jsonb, '["ត្រី ៤០០ ក្រាម", "ទឹកអំពិល ២ ស្លាបព្រាបាយ", "ម្នាស់ ១ កែវ", "ប៉េងប៉ោះ ២ ផ្លែ", "ត្រកួន ឬជីរ", "ទឹកត្រី ១ ស្លាបព្រាបាយ"]'::jsonb, '["Clean the fish, cut into thick slices and season with a pinch of salt.", "Mix the tamarind paste with 100 ml warm water and strain out any seeds.", "Bring 1.2 litres of water to the boil and add the tamarind water and the pineapple.", "Simmer 5 minutes so the pineapple softens and sweetens the broth.", "Add the fish and cut tomatoes and simmer gently for 6 to 8 minutes, without stirring so the fish stays whole.", "Season with fish sauce and a little sugar; taste: it should be sour first, then salty and slightly sweet.", "Add the morning glory or herbs, cook 1 minute more, and serve hot with rice."]'::jsonb, '["លាងត្រីឱ្យស្អាត កាត់ជាកង់ក្រាស់ៗ ហើយរោយអំបិលបន្តិច។", "លាយអំពិលជាមួយទឹកឧណ្ហៗ ១០០ មីលីលីត្រ ហើយចម្រោះយកគ្រាប់ចេញ។", "ដាំទឹក ១,២ លីត្រឱ្យពុះ ហើយដាក់ទឹកអំពិល និងម្នាស់។", "រំងាស់ ៥ នាទី ឱ្យម្នាស់ទន់ ហើយធ្វើឱ្យទឹកសម្លផ្អែមល្មម។", "ដាក់ត្រី និងប៉េងប៉ោះកាត់ ហើយរំងាស់ស្រាលៗ ៦ ទៅ ៨ នាទី កុំកូរ ដើម្បីកុំឱ្យត្រីបែក។", "ដាក់ទឹកត្រី និងស្ករបន្តិច។ ភ្លក់មើល៖ ជូរមុន រួចប្រៃ និងផ្អែមបន្តិច។", "ដាក់ត្រកួន ឬជីរ ស្ងោរ ១ នាទីទៀត ហើយញ៉ាំក្តៅៗជាមួយបាយ។"]'::jsonb),
('Khmer Chicken Curry', 'សម្លការីសាច់មាន់', 'Mild coconut curry with chicken, potato and sweet potato.', 'ការីសាច់មាន់ខ្ទិះដូងស្រាល ជាមួយដំឡូងបារាំង និងដំឡូងជ្វា។', 480, 'KH', 'curry', 50, 4, 'medium', false, 88, null, null, null, '["500 g chicken", "3 tbsp red curry kroeung", "400 ml coconut milk", "2 potatoes", "1 sweet potato", "1 onion"]'::jsonb, '["សាច់មាន់ ៥០០ ក្រាម", "គ្រឿងការីក្រហម ៣ ស្លាបព្រាបាយ", "ខ្ទិះដូង ៤០០ មីលីលីត្រ", "ដំឡូងបារាំង ២ មើម", "ដំឡូងជ្វា ១ មើម", "ខ្ទឹមបារាំង ១ មើម"]'::jsonb, '["Cut the chicken into large pieces and season with a pinch of salt.", "Peel the potatoes and sweet potato and cut into big chunks; cut the onion into wedges.", "Fry the potato and sweet potato in a little oil for 5 minutes until lightly golden, then set aside.", "In a large pot, fry the curry kroeung in 1 tbsp oil on medium heat for 2 to 3 minutes until fragrant and darker.", "Add the chicken and stir until it is coated and no longer pink outside.", "Pour in the coconut milk and 300 ml water, bring to a gentle boil and simmer 20 minutes.", "Add the potatoes, sweet potato and onion and simmer another 15 minutes until everything is tender.", "Season with salt and a little sugar, then serve hot with bread or rice."]'::jsonb, '["កាត់សាច់មាន់ជាដុំធំៗ ហើយរោយអំបិលបន្តិច។", "ចិតដំឡូងបារាំង និងដំឡូងជ្វា ហើយកាត់ជាដុំធំៗ ហើយកាត់ខ្ទឹមបារាំងជាចំណិត។", "ចៀនដំឡូងទាំងពីរក្នុងប្រេងបន្តិច ៥ នាទី រហូតលឿងស្រាល រួចទុកមួយឡែក។", "ក្នុងឆ្នាំងធំ លីងគ្រឿងការីក្នុងប្រេង ១ ស្លាបព្រាបាយ ភ្លើងមធ្យម ២ ទៅ ៣ នាទី រហូតឈ្ងុយ។", "ដាក់សាច់មាន់ ហើយកូរឱ្យសព្វគ្រឿង រហូតខាងក្រៅលែងក្រហម។", "ចាក់ខ្ទិះដូង និងទឹក ៣០០ មីលីលីត្រ ស្ងោរឱ្យពុះស្រាល ហើយរំងាស់ ២០ នាទី។", "ដាក់ដំឡូង និងខ្ទឹមបារាំង រំងាស់ ១៥ នាទីទៀត រហូតទន់ទាំងអស់។", "ដាក់អំបិល និងស្ករបន្តិច ហើយញ៉ាំក្តៅៗជាមួយនំបុ័ង ឬបាយ។"]'::jsonb),
('Samlor Korko', 'សម្លកកូរ', 'Thick Khmer stirred soup with pork, vegetables and toasted rice.', 'សម្លកកូរខាប់ ជាមួយសាច់ជ្រូក បន្លែ និងអង្ករលីង។', 390, 'KH', 'soup', 60, 4, 'hard', false, 86, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/e/ee/Samlor_Korko_Khmer_at_Peace_Cafe.jpg/500px-Samlor_Korko_Khmer_at_Peace_Cafe.jpg', 'Photo: Mx. Granger, CC0, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Samlor_Korko_Khmer_at_Peace_Cafe.jpg', '["300 g pork", "2 tbsp toasted rice powder", "Eggplant, pumpkin and green papaya", "3 tbsp kroeung paste", "1 tbsp prahok", "Herbs"]'::jsonb, '["សាច់ជ្រូក ៣០០ ក្រាម", "អង្ករលីងបុក ២ ស្លាបព្រាបាយ", "ត្រប់ ល្ពៅ និងល្ហុងខ្ចី", "គ្រឿង ៣ ស្លាបព្រាបាយ", "ប្រហុក ១ ស្លាបព្រាបាយ", "ជីរ"]'::jsonb, '["Cut the pork into small thin pieces.", "Peel and cut the pumpkin and green papaya into chunks; cut the eggplant into pieces.", "Heat 1 tbsp oil in a pot and fry the kroeung paste on medium heat for 2 minutes until fragrant.", "Add the prahok and the pork and stir-fry for 3 to 4 minutes until the pork is cooked outside.", "Pour in 1.5 litres of water and bring to the boil.", "Add the papaya and pumpkin first and simmer 10 minutes, then add the eggplant for 5 more minutes.", "Mix the toasted rice powder with a little water and stir it in slowly; keep stirring for 3 minutes as the soup thickens.", "Season with salt and a pinch of sugar, add the herbs, and serve hot with rice."]'::jsonb, '["កាត់សាច់ជ្រូកជាដុំតូចៗស្តើងៗ។", "ចិតល្ពៅ និងល្ហុងខ្ចី ហើយកាត់ជាដុំ ហើយកាត់ត្រប់ជាដុំៗ។", "កម្តៅប្រេង ១ ស្លាបព្រាបាយក្នុងឆ្នាំង ហើយលីងគ្រឿងលើភ្លើងមធ្យម ២ នាទី រហូតឈ្ងុយ។", "ដាក់ប្រហុក និងសាច់ជ្រូក ហើយឆា ៣ ទៅ ៤ នាទី រហូតសាច់ឆ្អិនខាងក្រៅ។", "ចាក់ទឹក ១,៥ លីត្រ ហើយស្ងោរឱ្យពុះ។", "ដាក់ល្ហុង និងល្ពៅមុន រំងាស់ ១០ នាទី រួចដាក់ត្រប់ ៥ នាទីទៀត។", "លាយអង្ករលីងបុកជាមួយទឹកបន្តិច ហើយដាក់ចូលយឺតៗ កូរជាប់ ៣ នាទី រហូតសម្លខាប់។", "ដាក់អំបិល និងស្ករបន្តិច ដាក់ជីរ ហើយញ៉ាំក្តៅៗជាមួយបាយ។"]'::jsonb),
('Num Kachay', 'នំកាឆាយ', 'Crisp fried chive cakes with a sweet and sour dip.', 'នំកាឆាយចៀនស្រួយ ជាមួយទឹកជ្រលក់ជូរផ្អែម។', 300, 'KH', 'snack', 40, 4, 'medium', false, 84, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/c/cf/Cambodian_deep-fried_chive_cakes.jpg/500px-Cambodian_deep-fried_chive_cakes.jpg', 'Photo: Jason Eppink from New York City, USA, CC BY 2.0, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Cambodian_deep-fried_chive_cakes.jpg', '["200 g rice flour", "2 tbsp tapioca starch", "1 bunch Chinese chives", "Oil for frying", "Sweet fish sauce dip"]'::jsonb, '["ម្សៅអង្ករ ២០០ ក្រាម", "ម្សៅដំឡូងមី ២ ស្លាបព្រាបាយ", "គូឆាយ ១ ចង្កោម", "ប្រេងសម្រាប់ចៀន", "ទឹកត្រីផ្អែមជ្រលក់"]'::jsonb, '["Wash the chives, dry them well and cut into 1 cm pieces.", "In a bowl, mix the rice flour, tapioca starch and a pinch of salt.", "Slowly stir in about 300 ml of hot water until you get a soft, sticky dough.", "Fold in the chives so they are spread evenly through the dough.", "With oiled hands, shape round cakes about 1.5 cm thick.", "Steam the cakes for 10 minutes so the dough sets, then let them cool slightly.", "Heat a little oil in a pan and fry the cakes on medium heat for 3 to 4 minutes per side until golden and crisp.", "Serve hot with the sweet fish sauce dip."]'::jsonb, '["លាងគូឆាយ ជូតឱ្យស្ងួត ហើយកាត់ជាកង់ ១ សង់ទីម៉ែត្រ។", "ក្នុងចាន លាយម្សៅអង្ករ ម្សៅដំឡូងមី និងអំបិលបន្តិច។", "ចាក់ទឹកក្តៅប្រហែល ៣០០ មីលីលីត្រ យឺតៗ កូររហូតបានម្សៅទន់ស្អិត។", "ច្របល់គូឆាយចូលឱ្យសព្វ។", "លាបប្រេងដៃ ហើយធ្វើជាដុំមូលក្រាស់ ១,៥ សង់ទីម៉ែត្រ។", "ចំហុយនំ ១០ នាទី ឱ្យម្សៅស្អិត រួចទុកឱ្យត្រជាក់បន្តិច។", "កម្តៅប្រេងបន្តិចក្នុងខ្ទះ ហើយចៀនភ្លើងមធ្យមម្ខាង ៣ ទៅ ៤ នាទី រហូតលឿងស្រួយ។", "ញ៉ាំក្តៅៗជាមួយទឹកត្រីផ្អែម។"]'::jsonb),
('Lemongrass Beef Stir-fry', 'ឆាគ្រឿងសាច់គោ', 'Beef stir-fried with lemongrass kroeung, chili and green beans.', 'សាច់គោឆាគ្រឿងស្លឹកគ្រៃ ជាមួយម្ទេស និងសណ្តែកកួរ។', 430, 'KH', 'main', 25, 2, 'easy', false, 82, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/8/80/Cha_kroeung.jpg/500px-Cha_kroeung.jpg', 'Photo: Thomas Wanhoff, CC BY-SA 2.0, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Cha_kroeung.jpg', '["250 g beef", "2 tbsp lemongrass kroeung", "1 chili", "100 g green beans", "1 tbsp fish sauce", "1 tbsp oil"]'::jsonb, '["សាច់គោ ២៥០ ក្រាម", "គ្រឿងស្លឹកគ្រៃ ២ ស្លាបព្រាបាយ", "ម្ទេស ១ គ្រាប់", "សណ្តែកកួរ ១០០ ក្រាម", "ទឹកត្រី ១ ស្លាបព្រាបាយ", "ប្រេង ១ ស្លាបព្រាបាយ"]'::jsonb, '["Slice the beef very thinly across the grain; this keeps it tender.", "Mix the beef with half of the kroeung and a pinch of sugar and leave 10 minutes.", "Top and tail the green beans and cut into 4 cm pieces; slice the chili.", "Heat the oil in a wok on high heat and fry the rest of the kroeung and the chili for 30 seconds.", "Add the beans with a splash of water and stir-fry 2 minutes until bright green.", "Push the beans aside, add the beef and spread it out; leave 30 seconds, then stir-fry 2 minutes.", "Season with the fish sauce, toss everything together and serve at once with rice."]'::jsonb, '["ហាន់សាច់គោឱ្យស្តើងបំផុតឆ្លងសរសៃ ដើម្បីឱ្យទន់។", "ប្រឡាក់សាច់គោជាមួយគ្រឿងពាក់កណ្តាល និងស្ករបន្តិច ហើយទុក ១០ នាទី។", "កាត់ចុងសណ្តែកកួរ ហើយកាត់ជាកង់ ៤ សង់ទីម៉ែត្រ ហើយហាន់ម្ទេស។", "កម្តៅប្រេងក្នុងខ្ទះលើភ្លើងខ្លាំង ហើយលីងគ្រឿងដែលនៅសល់ និងម្ទេស ៣០ វិនាទី។", "ដាក់សណ្តែកកួរ និងទឹកបន្តិច ឆា ២ នាទី រហូតបៃតងភ្លឺ។", "រុញសណ្តែកទៅម្ខាង ដាក់សាច់គោឱ្យរាល ទុក ៣០ វិនាទី រួចឆា ២ នាទី។", "ដាក់ទឹកត្រី ច្របល់ឱ្យសព្វ ហើយញ៉ាំភ្លាមជាមួយបាយ។"]'::jsonb),
('Chicken Fried Rice', 'បាយឆាសាច់មាន់', 'Quick wok-fried rice with chicken, egg and tomato.', 'បាយឆារហ័ស ជាមួយសាច់មាន់ ស៊ុត និងប៉េងប៉ោះ។', 520, 'KH', 'rice', 20, 2, 'easy', false, 80, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/9/95/Hongkong_Fried_Rice_2.jpg/500px-Hongkong_Fried_Rice_2.jpg', 'Photo: Bajinra, CC0, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Hongkong_Fried_Rice_2.jpg', '["2 cups cooked rice", "1 chicken breast", "2 eggs", "1 tomato", "1 tbsp fish sauce", "1 tbsp oil"]'::jsonb, '["បាយ ២ កែវ", "សាច់ទ្រូងមាន់ ១ ដុំ", "ស៊ុត ២ គ្រាប់", "ប៉េងប៉ោះ ១ ផ្លែ", "ទឹកត្រី ១ ស្លាបព្រាបាយ", "ប្រេង ១ ស្លាបព្រាបាយ"]'::jsonb, '["Use rice cooked the day before if you can; break up any lumps with your fingers.", "Cut the chicken breast into small cubes and season with a pinch of salt and pepper.", "Cut the tomato into small pieces and beat the eggs with a pinch of salt.", "Heat the oil in a wok on high heat and stir-fry the chicken for 4 to 5 minutes until cooked, then push it aside.", "Pour the eggs into the empty side, scramble until just set, then mix with the chicken.", "Add the rice and stir-fry for 3 minutes, pressing it against the hot wok so every grain heats through.", "Add the tomato and fish sauce and stir-fry 1 more minute.", "Taste, add salt or pepper if needed, and serve hot."]'::jsonb, '["ប្រើបាយដែលដាំពីម្សិលមិញបើអាច ហើយញែកដុំៗដោយដៃ។", "កាត់សាច់ទ្រូងមាន់ជាដុំតូចៗ ហើយរោយអំបិល និងម្រេចបន្តិច។", "កាត់ប៉េងប៉ោះជាដុំតូចៗ ហើយវាយស៊ុតជាមួយអំបិលបន្តិច។", "កម្តៅប្រេងក្នុងខ្ទះលើភ្លើងខ្លាំង ឆាសាច់មាន់ ៤ ទៅ ៥ នាទី រហូតឆ្អិន រួចរុញទៅម្ខាង។", "ចាក់ស៊ុតនៅម្ខាងទៀត កូររហូតស៊ុតទើបតែស្អិត រួចច្របល់ជាមួយសាច់មាន់។", "ដាក់បាយ ហើយឆា ៣ នាទី សង្កត់នឹងខ្ទះក្តៅ ដើម្បីឱ្យបាយក្តៅសព្វ។", "ដាក់ប៉េងប៉ោះ និងទឹកត្រី ហើយឆា ១ នាទីទៀត។", "ភ្លក់មើល បន្ថែមអំបិល ឬម្រេចបើចាំបាច់ ហើយញ៉ាំក្តៅៗ។"]'::jsonb),
('Prahok Ktis', 'ប្រហុកខ្ទិះ', 'Creamy pork and prahok dip in coconut milk, eaten with fresh vegetables.', 'ប្រហុកខ្ទិះសាច់ជ្រូក ខ្ទិះដូង ញ៉ាំជាមួយបន្លែស្រស់។', 450, 'KH', 'main', 30, 4, 'medium', false, 79, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/c/cc/Prahok_ktiss.jpg/500px-Prahok_ktiss.jpg', 'Photo: Timothy Vollmer, CC BY 2.0, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Prahok_ktiss.jpg', '["200 g minced pork", "2 tbsp prahok", "300 ml coconut milk", "2 tbsp kroeung paste", "3 pea eggplants", "Fresh vegetables to dip"]'::jsonb, '["សាច់ជ្រូកចិញ្ច្រាំ ២០០ ក្រាម", "ប្រហុក ២ ស្លាបព្រាបាយ", "ខ្ទិះដូង ៣០០ មីលីលីត្រ", "គ្រឿង ២ ស្លាបព្រាបាយ", "ត្រប់ពុត ៣ គ្រាប់", "បន្លែស្រស់សម្រាប់ជ្រលក់"]'::jsonb, '["Mash the prahok with 3 tbsp water and strain it to remove bones; keep the liquid.", "Pour 150 ml of the coconut milk into a pot and simmer on medium heat until the oil starts to separate.", "Add the kroeung paste and fry it in the coconut cream for 2 minutes until fragrant.", "Add the minced pork and stir, breaking it up, for 4 to 5 minutes until cooked.", "Stir in the strained prahok and the rest of the coconut milk.", "Simmer gently for 10 minutes, stirring often, until thick and creamy; season with a little sugar.", "Add the pea eggplants for the last 3 minutes.", "Serve warm as a dip with the fresh vegetables and rice."]'::jsonb, '["កិនប្រហុកជាមួយទឹក ៣ ស្លាបព្រាបាយ ហើយចម្រោះយកឆ្អឹងចេញ ទុកតែទឹក។", "ចាក់ខ្ទិះដូង ១៥០ មីលីលីត្រក្នុងឆ្នាំង ហើយរំងាស់ភ្លើងមធ្យម រហូតប្រេងដូងចាប់ផ្តើមបែក។", "ដាក់គ្រឿង ហើយលីងក្នុងខ្ទិះដូង ២ នាទី រហូតឈ្ងុយ។", "ដាក់សាច់ជ្រូកចិញ្ច្រាំ ហើយកូរញែក ៤ ទៅ ៥ នាទី រហូតឆ្អិន។", "ដាក់ទឹកប្រហុកចម្រោះ និងខ្ទិះដូងដែលនៅសល់។", "រំងាស់ស្រាលៗ ១០ នាទី កូរញឹកញាប់ រហូតខាប់ខាប់ ដាក់ស្ករបន្តិច។", "ដាក់ត្រប់ពុត ៣ នាទីចុងក្រោយ។", "ញ៉ាំឧណ្ហៗជាទឹកជ្រលក់ ជាមួយបន្លែស្រស់ និងបាយ។"]'::jsonb),
('Kdam Chhar', 'ក្តាមឆាម្រេចខ្ចី', 'Crab stir-fried with fresh Kampot green peppercorns.', 'ក្តាមឆាជាមួយម្រេចខ្ចីកំពត។', 330, 'KH', 'main', 30, 2, 'medium', true, 78, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7b/Fried_crab_with_green_pepper.jpg/500px-Fried_crab_with_green_pepper.jpg', 'Photo: eric yeargan, CC BY 2.0, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Fried_crab_with_green_pepper.jpg', '["2 blue crabs", "3 stems fresh green peppercorns", "3 cloves garlic", "1 tbsp oyster sauce", "1 tbsp fish sauce", "1 tbsp oil"]'::jsonb, '["ក្តាមសេះ ២ ក្បាល", "ម្រេចខ្ចី ៣ ចង្កោម", "ខ្ទឹមស ៣ កំពឹស", "ប្រេងខ្យង ១ ស្លាបព្រាបាយ", "ទឹកត្រី ១ ស្លាបព្រាបាយ", "ប្រេង ១ ស្លាបព្រាបាយ"]'::jsonb, '["Scrub the crabs, pull off the top shells, remove the gills and cut each body in half; crack the claws lightly.", "Pick the green peppercorns from their stems, keeping a few small bunches whole.", "Crush the garlic.", "Heat the oil in a wok on high heat and fry the garlic for 20 seconds until golden.", "Add the crab and stir-fry for 3 minutes.", "Add 4 tbsp water, cover and cook 3 to 4 minutes until the shells turn bright red.", "Add the peppercorns, oyster sauce, fish sauce and a pinch of sugar and toss for 2 minutes until the sauce coats the crab.", "Serve hot with rice."]'::jsonb, '["ដុសក្តាម បកក្រដោងលើ យកស្រកីចេញ ហើយកាត់ខ្លួនពាក់កណ្តាល ហើយបំបែកក្តៀបបន្តិច។", "បេះម្រេចខ្ចីពីទង ទុកចង្កោមតូចៗខ្លះទាំងមូល។", "ចិញ្ច្រាំខ្ទឹមស។", "កម្តៅប្រេងក្នុងខ្ទះលើភ្លើងខ្លាំង ហើយលីងខ្ទឹមស ២០ វិនាទី រហូតលឿង។", "ដាក់ក្តាម ហើយឆា ៣ នាទី។", "ដាក់ទឹក ៤ ស្លាបព្រាបាយ គ្រប ហើយចម្អិន ៣ ទៅ ៤ នាទី រហូតសំបកក្រហមភ្លឺ។", "ដាក់ម្រេចខ្ចី ប្រេងខ្យង ទឹកត្រី និងស្ករបន្តិច ហើយឆា ២ នាទី ឱ្យទឹកជាប់ក្តាម។", "ញ៉ាំក្តៅៗជាមួយបាយ។"]'::jsonb),
('Num Pang', 'នំបុ័ងសាច់', 'Khmer baguette sandwich with pâté, meat, pickles and herbs.', 'នំបុ័ងខ្មែរ ជាមួយប៉ាតេ សាច់ ជ្រក់ និងជីរ។', 480, 'KH', 'snack', 15, 1, 'easy', true, 77, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/a/aa/Catfish_peppercorn_num_pang.jpg/500px-Catfish_peppercorn_num_pang.jpg', 'Photo: Krista, CC BY 2.0, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Catfish_peppercorn_num_pang.jpg', '["1 baguette", "2 tbsp pâté", "80 g grilled pork or cold cuts", "Pickled carrot and papaya", "Cucumber and cilantro", "Chili sauce"]'::jsonb, '["នំបុ័ង ១ ដើម", "ប៉ាតេ ២ ស្លាបព្រាបាយ", "សាច់ជ្រូកអាំង ឬសាច់ក្រក ៨០ ក្រាម", "ជ្រក់ការ៉ុត និងល្ហុង", "ត្រសក់ និងជីវ៉ាន់ស៊ុយ", "ទឹកម្ទេស"]'::jsonb, '["If using raw pork, slice it thinly, season with salt, pepper and a pinch of sugar, and grill 2 minutes per side.", "Slice the cucumber into thin sticks and pick the cilantro leaves.", "Warm the baguette in a hot oven or pan for 3 minutes so the crust is crisp.", "Cut the bread open along one side without cutting all the way through.", "Spread the pâté thickly on the inside.", "Lay in the pork or cold cuts, then the pickled carrot and papaya.", "Add the cucumber and cilantro, drizzle with chili sauce and eat while the bread is warm."]'::jsonb, '["បើប្រើសាច់ជ្រូកឆៅ ហាន់ស្តើងៗ រោយអំបិល ម្រេច និងស្ករបន្តិច ហើយអាំងម្ខាង ២ នាទី។", "ហាន់ត្រសក់ជាបន្ទះតូចៗ ហើយបេះស្លឹកជីវ៉ាន់ស៊ុយ។", "កម្តៅនំបុ័ងក្នុងឡ ឬខ្ទះក្តៅ ៣ នាទី ឱ្យសំបកស្រួយ។", "វះនំបុ័ងតាមបណ្តោយម្ខាង កុំឱ្យដាច់។", "លាបប៉ាតេក្រាស់ៗខាងក្នុង។", "ដាក់សាច់ជ្រូក ឬសាច់ក្រក រួចដាក់ជ្រក់ការ៉ុត និងល្ហុង។", "ដាក់ត្រសក់ និងជីវ៉ាន់ស៊ុយ ស្រោចទឹកម្ទេស ហើយញ៉ាំពេលនំបុ័ងនៅក្តៅ។"]'::jsonb),
('Samlor Machu Youn', 'សម្លម្ជូរយួន', 'Sweet and sour fish soup with pineapple, tomato and herbs.', 'សម្លម្ជូរយួនជូរផ្អែម ជាមួយម្នាស់ ប៉េងប៉ោះ និងជីរ។', 220, 'KH', 'soup', 35, 4, 'easy', false, 76, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/8/8e/Canh_chua_c%C3%A1_l%C3%B3c_%E1%BB%9F_Th%E1%BB%A7y_Tr%C3%BAc_Qu%C3%A1n%2C_%C4%91%C6%B0%E1%BB%9Dng_Nguy%E1%BB%85n_Nh%E1%BB%AF_L%C3%A3m_%281%29.jpg/500px-Canh_chua_c%C3%A1_l%C3%B3c_%E1%BB%9F_Th%E1%BB%A7y_Tr%C3%BAc_Qu%C3%A1n%2C_%C4%91%C6%B0%E1%BB%9Dng_Nguy%E1%BB%85n_Nh%E1%BB%AF_L%C3%A3m_%281%29.jpg', 'Photo: Phương Huy (thảo luận), Public domain, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Canh_chua_c%C3%A1_l%C3%B3c_%E1%BB%9F_Th%E1%BB%A7y_Tr%C3%BAc_Qu%C3%A1n,_%C4%91%C6%B0%E1%BB%9Dng_Nguy%E1%BB%85n_Nh%E1%BB%AF_L%C3%A3m_(1).jpg', '["400 g catfish", "2 tbsp tamarind paste", "1 cup pineapple", "2 tomatoes", "Bean sprouts and lotus stems", "Rice paddy herb and fried garlic"]'::jsonb, '["ត្រីអណ្តែង ៤០០ ក្រាម", "ទឹកអំពិល ២ ស្លាបព្រាបាយ", "ម្នាស់ ១ កែវ", "ប៉េងប៉ោះ ២ ផ្លែ", "សណ្តែកបណ្តុះ និងក្រអៅឈូក", "ម្អម និងខ្ទឹមចៀន"]'::jsonb, '["Clean the catfish, cut into thick steaks and season with a pinch of salt.", "Mix the tamarind paste with 100 ml warm water and strain.", "Peel the lotus stems and cut into 4 cm pieces; cut the tomatoes into wedges.", "Bring 1.2 litres of water to the boil with the tamarind water, the pineapple and 1 tbsp sugar.", "Add the fish and simmer gently for 8 minutes; skim off any foam.", "Add the tomatoes and lotus stems and cook 2 minutes.", "Season with salt or fish sauce: the soup should taste sour, sweet and salty together.", "Turn off the heat, add the bean sprouts and rice paddy herb, and top with fried garlic. Serve with rice."]'::jsonb, '["លាងត្រីអណ្តែង កាត់ជាកង់ក្រាស់ ហើយរោយអំបិលបន្តិច។", "លាយអំពិលជាមួយទឹកឧណ្ហៗ ១០០ មីលីលីត្រ ហើយចម្រោះ។", "បកសំបកក្រអៅឈូក កាត់ជាកង់ ៤ សង់ទីម៉ែត្រ ហើយកាត់ប៉េងប៉ោះជាចំណិត។", "ដាំទឹក ១,២ លីត្រជាមួយទឹកអំពិល ម្នាស់ និងស្ករ ១ ស្លាបព្រាបាយ ឱ្យពុះ។", "ដាក់ត្រី ហើយរំងាស់ស្រាលៗ ៨ នាទី ហើយដួសពពុះចេញ។", "ដាក់ប៉េងប៉ោះ និងក្រអៅឈូក ស្ងោរ ២ នាទី។", "ដាក់អំបិល ឬទឹកត្រី៖ សម្លគួរមានរសជាតិជូរ ផ្អែម និងប្រៃ។", "បិទភ្លើង ដាក់សណ្តែកបណ្តុះ និងម្អម ហើយរោយខ្ទឹមចៀន។ ញ៉ាំជាមួយបាយ។"]'::jsonb),
('Num Ansom', 'នំអន្សម', 'Sticky rice cake with banana, wrapped in banana leaf and boiled.', 'នំអន្សមចេក ធ្វើពីបាយដំណើប ខ្ចប់ស្លឹកចេក ហើយស្ងោរ។', 320, 'KH', 'sweet', 120, 6, 'hard', false, 75, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/0/05/Num_ansom_chek_Khmer_Cambodian_dessert_rice_cake.jpg/500px-Num_ansom_chek_Khmer_Cambodian_dessert_rice_cake.jpg', 'Photo: MoonsMoon, CC BY 4.0, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Num_ansom_chek_Khmer_Cambodian_dessert_rice_cake.jpg', '["500 g sticky rice", "200 ml coconut milk", "3 ripe bananas", "1 tsp salt", "2 tbsp sugar", "Banana leaves and string"]'::jsonb, '["អង្ករដំណើប ៥០០ ក្រាម", "ខ្ទិះដូង ២០០ មីលីលីត្រ", "ចេកទុំ ៣ ផ្លែ", "អំបិល ១ ស្លាបព្រាកាហ្វេ", "ស្ករ ២ ស្លាបព្រាបាយ", "ស្លឹកចេក និងខ្សែ"]'::jsonb, '["Wash the sticky rice until the water runs clear, then soak it for 4 hours or overnight and drain.", "Warm the coconut milk with the salt and sugar until dissolved; do not boil.", "Mix the coconut milk into the rice and leave 15 minutes so the rice absorbs it.", "Peel the bananas and cut each in half lengthways.", "Wipe the banana leaves and soften them over a flame so they fold without cracking.", "Lay a leaf flat, spread a layer of rice, place a banana half in the middle and cover it with more rice.", "Roll the leaf tightly into a log, fold in the ends and tie firmly with string in three places.", "Boil the rolls fully covered with water for 90 minutes, adding hot water when needed.", "Let them cool for at least 30 minutes before slicing so the rice firms up."]'::jsonb, '["លាងអង្ករដំណើបរហូតទឹកថ្លា រួចត្រាំ ៤ ម៉ោង ឬមួយយប់ ហើយស្រង់។", "កម្តៅខ្ទិះដូងជាមួយអំបិល និងស្ករ រហូតរលាយ កុំឱ្យពុះ។", "ច្របល់ខ្ទិះដូងជាមួយអង្ករ ហើយទុក ១៥ នាទី ឱ្យអង្ករស្រូបចូល។", "បកចេក ហើយពុះពាក់កណ្តាលតាមបណ្តោយ។", "ជូតស្លឹកចេក ហើយអាំងលើភ្លើងឱ្យទន់ ដើម្បីកុំឱ្យប្រេះពេលបត់។", "ក្រាលស្លឹក ពង្រាយអង្ករមួយស្រទាប់ ដាក់ចេកពាក់កណ្តាលនៅកណ្តាល ហើយគ្របដោយអង្ករទៀត។", "រមូរស្លឹកឱ្យណែនជារាងមូលវែង បត់ចុងទាំងសងខាង ហើយចងខ្សែឱ្យណែន ៣ កន្លែង។", "ស្ងោរនំដោយទឹកលិចទាំងស្រុង ៩០ នាទី បន្ថែមទឹកក្តៅពេលចាំបាច់។", "ទុកឱ្យត្រជាក់យ៉ាងតិច ៣០ នាទី មុនកាត់ ដើម្បីឱ្យអង្ករស្អិតល្អ។"]'::jsonb),
('Tuk Ampov', 'ទឹកអំពៅ', 'Fresh-pressed sugarcane juice with a squeeze of lime over ice.', 'ទឹកអំពៅកិនស្រស់ ជាមួយក្រូចឆ្មាបន្តិច និងទឹកកក។', 180, 'KH', 'drinks', 10, 2, 'easy', false, 74, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a2/Sugar_cane_juice_in_Phnom_Penh_4.jpg/500px-Sugar_cane_juice_in_Phnom_Penh_4.jpg', 'Photo: Mx. Granger, CC0, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Sugar_cane_juice_in_Phnom_Penh_4.jpg', '["4 sticks peeled sugarcane", "1 calamansi or lime", "Ice"]'::jsonb, '["អំពៅចិតសំបក ៤ ដើម", "ក្រូចឆ្មា ១ ផ្លែ", "ទឹកកក"]'::jsonb, '["Wash the peeled sugarcane and cut it into pieces that fit your juicer or press.", "Chill the cane in the fridge for 30 minutes if you can; cold cane gives a fresher taste.", "Press the cane through a sugarcane press or juicer; fold and press each piece twice to get all the juice.", "Strain the juice through a fine sieve to remove fibres.", "Squeeze in the lime and stir.", "Fill two glasses with ice, pour the juice over and drink at once before it darkens."]'::jsonb, '["លាងអំពៅដែលចិតរួច ហើយកាត់ជាកង់ល្មមដាក់ម៉ាស៊ីនកិន។", "ដាក់អំពៅក្នុងទូទឹកកក ៣០ នាទីបើអាច ព្រោះអំពៅត្រជាក់ធ្វើឱ្យរសជាតិស្រស់។", "កិនអំពៅតាមម៉ាស៊ីនកិនអំពៅ ឬម៉ាស៊ីនក្រឡុក បត់ហើយកិនម្តងទៀត ដើម្បីបានទឹកទាំងអស់។", "ចម្រោះទឹកតាមកន្ត្រងល្អិត ដើម្បីយកសរសៃចេញ។", "ច្របាច់ក្រូចឆ្មាចូល ហើយកូរ។", "ដាក់ទឹកកកក្នុងកែវពីរ ចាក់ទឹកអំពៅពីលើ ហើយផឹកភ្លាម មុនពណ៌ប្រែខ្មៅ។"]'::jsonb),
('Pizza Margherita', 'ភីហ្សាម៉ាហ្គារីតា', 'Neapolitan pizza with tomato, mozzarella and fresh basil.', 'ភីហ្សាណាប៉ូលី ជាមួយប៉េងប៉ោះ ឈីសម៉ូហ្សារ៉ែឡា និងជីរនាងវង។', 700, 'IT', 'main', 90, 2, 'medium', false, 46, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/1/15/Margherita_pizza_on_plate_2.jpg/500px-Margherita_pizza_on_plate_2.jpg', 'Photo: Shisma, CC BY 4.0, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Margherita_pizza_on_plate_2.jpg', '["250 g pizza dough", "100 g crushed tomatoes", "125 g mozzarella", "Fresh basil", "1 tbsp olive oil"]'::jsonb, '["ម្សៅភីហ្សា ២៥០ ក្រាម", "ប៉េងប៉ោះកិន ១០០ ក្រាម", "ឈីសម៉ូហ្សារ៉ែឡា ១២៥ ក្រាម", "ជីរនាងវងស្រស់", "ប្រេងអូលីវ ១ ស្លាបព្រាបាយ"]'::jsonb, '["Take the dough out of the fridge 1 hour before, so it is soft and easy to stretch.", "Heat the oven to its highest setting (250 °C or more) with a baking tray inside for 30 minutes.", "Season the crushed tomatoes with a pinch of salt; drain the mozzarella and tear it into pieces.", "On a floured surface, press the dough out from the centre with your fingers into a 30 cm circle, leaving a thicker edge.", "Spread a thin layer of tomato, leaving the edge bare, and scatter the mozzarella over.", "Slide the pizza onto the hot tray and bake 8 to 10 minutes until the crust is puffed and spotted brown and the cheese bubbles.", "Add the fresh basil and a drizzle of olive oil, cut and serve straight away."]'::jsonb, '["យកម្សៅចេញពីទូទឹកកកមុន ១ ម៉ោង ឱ្យទន់ងាយពន្លាត។", "កម្តៅឡដល់កម្រិតខ្ពស់បំផុត (២៥០ អង្សា ឬលើស) ដាក់ថាសដុតនៅខាងក្នុង ៣០ នាទី។", "ដាក់អំបិលបន្តិចក្នុងប៉េងប៉ោះកិន ស្រង់ឈីសម៉ូហ្សារ៉ែឡា ហើយហែកជាដុំៗ។", "លើផ្ទៃរោយម្សៅ សង្កត់ម្សៅពីកណ្តាលចេញដោយម្រាមដៃ ឱ្យជារង្វង់ ៣០ សង់ទីម៉ែត្រ ទុកគែមក្រាស់។", "លាបប៉េងប៉ោះស្តើងៗ ទុកគែមទទេ ហើយរោយឈីសពីលើ។", "រំកិលភីហ្សាដាក់លើថាសក្តៅ ហើយដុត ៨ ទៅ ១០ នាទី រហូតគែមហើម មានស្នាមលឿង និងឈីសពុះ។", "ដាក់ជីរនាងវងស្រស់ និងប្រេងអូលីវបន្តិច កាត់ ហើយញ៉ាំភ្លាម។"]'::jsonb),
('Tiramisu', 'ធីរ៉ាមីស៊ូ', 'Italian layered dessert of coffee-soaked biscuits and mascarpone cream.', 'បង្អែមអ៊ីតាលីជាន់ៗ នំត្រាំកាហ្វេ និងក្រែមម៉ាស្ការផូន។', 450, 'IT', 'sweet', 30, 6, 'medium', false, 45, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/6/60/Tiramisu_at_Italian_restaurant_in_Japan.jpg/500px-Tiramisu_at_Italian_restaurant_in_Japan.jpg', 'Photo: Syced, CC0, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Tiramisu_at_Italian_restaurant_in_Japan.jpg', '["250 g mascarpone", "3 eggs", "80 g sugar", "200 g ladyfinger biscuits", "250 ml strong coffee", "Cocoa powder"]'::jsonb, '["ឈីសម៉ាស្ការផូន ២៥០ ក្រាម", "ស៊ុត ៣ គ្រាប់", "ស្ករ ៨០ ក្រាម", "នំស្ពុងស្រួយ ២០០ ក្រាម", "កាហ្វេខ្លាំង ២៥០ មីលីលីត្រ", "ម្សៅកាកាវ"]'::jsonb, '["Make the coffee and let it cool completely.", "Separate the eggs. Beat the yolks with the sugar for 3 to 4 minutes until pale and thick.", "Add the mascarpone and beat just until smooth.", "In a clean bowl, whisk the whites with a pinch of salt until they hold stiff peaks.", "Fold the whites into the mascarpone in three parts, gently, so the cream stays light.", "Dip each biscuit in the coffee for 1 second per side (no longer, or it gets soggy) and lay them in a dish.", "Spread half the cream on top, add another layer of dipped biscuits, then the rest of the cream.", "Cover and chill for at least 4 hours, ideally overnight.", "Dust with cocoa powder just before serving."]'::jsonb, '["ឆុងកាហ្វេ ហើយទុកឱ្យត្រជាក់ទាំងស្រុង។", "ញែកស៊ុត។ វាយស្នូលស៊ុតជាមួយស្ករ ៣ ទៅ ៤ នាទី រហូតស្លេក និងខាប់។", "ដាក់ឈីសម៉ាស្ការផូន ហើយវាយគ្រាន់តែឱ្យម៉ត់។", "ក្នុងចានស្អាតមួយទៀត វាយសស៊ុតជាមួយអំបិលបន្តិច រហូតរឹងជាកំពូល។", "ច្របល់សស៊ុតចូលក្នុងម៉ាស្ការផូនបីដង ថ្នមៗ ដើម្បីឱ្យក្រែមស្រាល។", "ជ្រលក់នំនីមួយៗក្នុងកាហ្វេម្ខាង ១ វិនាទី (កុំយូរពេក ក្រែងទន់ជោក) ហើយរៀបក្នុងថាស។", "លាបក្រែមពាក់កណ្តាលពីលើ ដាក់នំជ្រលក់មួយជាន់ទៀត រួចលាបក្រែមដែលនៅសល់។", "គ្រប ហើយដាក់ទូទឹកកកយ៉ាងតិច ៤ ម៉ោង ល្អបំផុតមួយយប់។", "រោយម្សៅកាកាវមុនញ៉ាំ។"]'::jsonb),
('Ratatouille', 'រ៉ាតាទូយ', 'Provençal stew of eggplant, zucchini, peppers and tomato in olive oil.', 'បន្លែខបែបប្រូវ៉ង់ស ជាមួយត្រប់ ត្រសក់បារាំង ម្ទេសប្លោក និងប៉េងប៉ោះ។', 220, 'FR', 'main', 60, 4, 'easy', false, 44, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/2/27/Ratatouille.jpg/500px-Ratatouille.jpg', 'Photo: Marcus Guimarães, CC BY 2.0, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Ratatouille.jpg', '["1 eggplant", "2 zucchini", "2 bell peppers", "4 tomatoes", "1 onion and 3 cloves garlic", "3 tbsp olive oil"]'::jsonb, '["ត្រប់ ១ ផ្លែ", "ត្រសក់បារាំង ២ ផ្លែ", "ម្ទេសប្លោក ២ ផ្លែ", "ប៉េងប៉ោះ ៤ ផ្លែ", "ខ្ទឹមបារាំង ១ និងខ្ទឹមស ៣ កំពឹស", "ប្រេងអូលីវ ៣ ស្លាបព្រាបាយ"]'::jsonb, '["Cut the eggplant and zucchini into 2 cm cubes, sprinkle with salt and leave 15 minutes; pat dry.", "Cut the peppers into strips, chop the onion and garlic, and roughly chop the tomatoes.", "Heat 1 tbsp olive oil in a large pan and fry the eggplant 5 minutes until golden; set aside. Do the same with the zucchini.", "Add the rest of the oil and cook the onion and peppers on medium heat for 8 minutes until soft.", "Add the garlic for 1 minute, then the tomatoes, and cook 5 minutes until they break down.", "Return the eggplant and zucchini, season with salt and pepper, cover and simmer on low heat for 30 minutes, stirring now and then.", "Taste and adjust the salt. Serve warm or at room temperature with bread."]'::jsonb, '["កាត់ត្រប់ និងត្រសក់បារាំងជាដុំការ៉េ ២ សង់ទីម៉ែត្រ រោយអំបិល ហើយទុក ១៥ នាទី រួចជូតឱ្យស្ងួត។", "កាត់ម្ទេសប្លោកជាបន្ទះ ចិញ្ច្រាំខ្ទឹមបារាំង និងខ្ទឹមស ហើយកាត់ប៉េងប៉ោះជាដុំធំៗ។", "កម្តៅប្រេងអូលីវ ១ ស្លាបព្រាបាយក្នុងខ្ទះធំ ចៀនត្រប់ ៥ នាទី រហូតលឿង រួចទុកមួយឡែក។ ធ្វើដូចគ្នាជាមួយត្រសក់។", "ដាក់ប្រេងដែលនៅសល់ ហើយឆាខ្ទឹមបារាំង និងម្ទេសប្លោកភ្លើងមធ្យម ៨ នាទី រហូតទន់។", "ដាក់ខ្ទឹមស ១ នាទី រួចដាក់ប៉េងប៉ោះ ហើយចម្អិន ៥ នាទី រហូតរលួយ។", "ដាក់ត្រប់ និងត្រសក់ចូលវិញ ដាក់អំបិល និងម្រេច គ្រប ហើយខភ្លើងតិច ៣០ នាទី កូរម្តងម្កាល។", "ភ្លក់ ហើយកែអំបិល។ ញ៉ាំឧណ្ហៗ ឬសីតុណ្ហភាពបន្ទប់ជាមួយនំបុ័ង។"]'::jsonb),
('Crème Brûlée', 'ក្រែមប្រ៊ុយឡេ', 'Vanilla custard with a crackly caramelised sugar top.', 'ក្រែមស៊ុតវ៉ានីឡា មានស្ករដុតស្រួយពីលើ។', 400, 'FR', 'sweet', 60, 4, 'medium', false, 43, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/f/fc/Cr%C3%A8me_br%C3%BBl%C3%A9e_at_restaurant_in_Zushi.jpg/500px-Cr%C3%A8me_br%C3%BBl%C3%A9e_at_restaurant_in_Zushi.jpg', 'Photo: Syced, CC0, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Cr%C3%A8me_br%C3%BBl%C3%A9e_at_restaurant_in_Zushi.jpg', '["500 ml cream", "5 egg yolks", "80 g sugar", "1 vanilla pod", "4 tbsp sugar for the top"]'::jsonb, '["ក្រែម ៥០០ មីលីលីត្រ", "ស្នូលស៊ុត ៥ គ្រាប់", "ស្ករ ៨០ ក្រាម", "វ៉ានីឡា ១ ដើម", "ស្ករ ៤ ស្លាបព្រាបាយសម្រាប់ដុតពីលើ"]'::jsonb, '["Heat the oven to 150 °C and put 4 small oven-proof dishes in a deep baking tray.", "Split the vanilla pod, scrape out the seeds and warm them in the cream until it just steams; do not boil.", "Whisk the yolks with the 80 g sugar until pale, then slowly whisk in the warm cream.", "Strain the mixture through a sieve and skim off any foam.", "Pour it into the dishes, then pour hot water into the tray to come halfway up the dishes.", "Bake 30 to 35 minutes until set at the edges but still wobbly in the centre.", "Cool, then chill in the fridge for at least 3 hours.", "Just before serving, sprinkle 1 tbsp sugar evenly over each and melt it with a kitchen torch until amber and crisp; let it harden 1 minute."]'::jsonb, '["កម្តៅឡ ១៥០ អង្សា ហើយដាក់ចានតូចទ្រាំកម្តៅ ៤ ក្នុងថាសដុតជ្រៅ។", "ពុះវ៉ានីឡា កោសគ្រាប់ចេញ ហើយកម្តៅក្នុងក្រែមរហូតហុយ កុំឱ្យពុះ។", "វាយស្នូលស៊ុតជាមួយស្ករ ៨០ ក្រាម រហូតស្លេក រួចចាក់ក្រែមឧណ្ហៗចូលយឺតៗទាំងវាយ។", "ចម្រោះល្បាយតាមកន្ត្រង ហើយដួសពពុះចេញ។", "ចាក់ដាក់ចាន រួចចាក់ទឹកក្តៅក្នុងថាសដល់ពាក់កណ្តាលចាន។", "ដុត ៣០ ទៅ ៣៥ នាទី រហូតគែមស្អិត ប៉ុន្តែកណ្តាលនៅញ័រ។", "ទុកឱ្យត្រជាក់ រួចដាក់ទូទឹកកកយ៉ាងតិច ៣ ម៉ោង។", "មុនញ៉ាំ រោយស្ករ ១ ស្លាបព្រាបាយឱ្យស្មើលើចាននីមួយៗ ហើយដុតដោយភ្លើងរហូតពណ៌ក្រហមលឿងស្រួយ ទុក ១ នាទីឱ្យរឹង។"]'::jsonb),
('Paella', 'ប៉ាអេយ៉ា', 'Spanish saffron rice cooked in a wide pan with seafood.', 'បាយអេស្ប៉ាញដាក់សាហ្វ្រង់ ដាំក្នុងខ្ទះធំ ជាមួយគ្រឿងសមុទ្រ។', 580, 'ES', 'rice', 60, 4, 'hard', false, 42, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a2/Paella_valenciana%2C_Mazatl%C3%A1n%2C_25_de_abril_de_2023.jpg/500px-Paella_valenciana%2C_Mazatl%C3%A1n%2C_25_de_abril_de_2023.jpg', 'Photo: El Nuevo Doge, CC0, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Paella_valenciana,_Mazatl%C3%A1n,_25_de_abril_de_2023.jpg', '["300 g paella rice", "1 litre fish stock", "300 g mixed seafood", "1 pinch saffron", "1 tomato and 1 bell pepper", "3 tbsp olive oil"]'::jsonb, '["អង្ករប៉ាអេយ៉ា ៣០០ ក្រាម", "ទឹកស៊ុបត្រី ១ លីត្រ", "គ្រឿងសមុទ្រចម្រុះ ៣០០ ក្រាម", "សាហ្វ្រង់ បន្តិច", "ប៉េងប៉ោះ ១ និងម្ទេសប្លោក ១", "ប្រេងអូលីវ ៣ ស្លាបព្រាបាយ"]'::jsonb, '["Warm the fish stock with the saffron and a pinch of salt and keep it hot.", "Grate the tomato and throw away the skin; cut the bell pepper into strips.", "Heat the olive oil in a wide paella pan and fry the pepper 3 minutes, then the tomato for 5 minutes until thick.", "Add the rice and stir 1 minute so every grain is coated.", "Pour in the hot stock, stir once to spread the rice evenly, then do not stir again.", "Cook on medium-high heat for 10 minutes.", "Press the seafood into the rice and cook on low heat 8 to 10 more minutes until the liquid is absorbed and the rice is tender.", "Turn the heat up for the last minute to crisp the bottom (you will hear it crackle).", "Cover with a cloth, rest 5 minutes and serve from the pan."]'::jsonb, '["កម្តៅទឹកស៊ុបត្រីជាមួយសាហ្វ្រង់ និងអំបិលបន្តិច ហើយទុកឱ្យក្តៅ។", "កោសប៉េងប៉ោះ ហើយបោះសំបកចោល កាត់ម្ទេសប្លោកជាបន្ទះ។", "កម្តៅប្រេងអូលីវក្នុងខ្ទះប៉ាអេយ៉ាធំទូលាយ ឆាម្ទេសប្លោក ៣ នាទី រួចប៉េងប៉ោះ ៥ នាទី រហូតខាប់។", "ដាក់អង្ករ ហើយកូរ ១ នាទី ឱ្យប្រឡាក់សព្វ។", "ចាក់ទឹកស៊ុបក្តៅ កូរម្តងឱ្យអង្កររាលស្មើ រួចកុំកូរទៀត។", "ចម្អិនភ្លើងខ្លាំងមធ្យម ១០ នាទី។", "សង្កត់គ្រឿងសមុទ្រចូលក្នុងអង្ករ ហើយចម្អិនភ្លើងតិច ៨ ទៅ ១០ នាទីទៀត រហូតទឹករីង និងបាយទន់។", "បង្កើនភ្លើងនៅនាទីចុងក្រោយ ឱ្យបាតក្រៀម (ឮសូរប្រេះៗ)។", "គ្របដោយក្រណាត់ ទុក ៥ នាទី ហើយញ៉ាំពីខ្ទះ។"]'::jsonb),
('Gazpacho', 'ស៊ុបត្រជាក់ហ្គាសប៉ាឆូ', 'Chilled Andalusian tomato and cucumber soup.', 'ស៊ុបប៉េងប៉ោះ និងត្រសក់ត្រជាក់ បែបអង់ដាលូស៊ី។', 150, 'ES', 'soup', 15, 4, 'easy', false, 41, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/3/35/Gazpacho_con_su_guarnici%C3%B3n_-_jlastras.jpg/500px-Gazpacho_con_su_guarnici%C3%B3n_-_jlastras.jpg', 'Photo: Javier Lastras from España/Spain, CC BY 2.0, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Gazpacho_con_su_guarnici%C3%B3n_-_jlastras.jpg', '["1 kg ripe tomatoes", "1 cucumber", "1 green pepper", "1 clove garlic", "3 tbsp olive oil", "1 tbsp vinegar"]'::jsonb, '["ប៉េងប៉ោះទុំ ១ គីឡូក្រាម", "ត្រសក់ ១ ផ្លែ", "ម្ទេសប្លោកបៃតង ១ ផ្លែ", "ខ្ទឹមស ១ កំពឹស", "ប្រេងអូលីវ ៣ ស្លាបព្រាបាយ", "ទឹកខ្មេះ ១ ស្លាបព្រាបាយ"]'::jsonb, '["Cut the tomatoes, peeled cucumber and green pepper into rough chunks; peel the garlic.", "Put them in a blender with 1 tsp salt and blend for 2 minutes until very smooth.", "With the blender running, slowly pour in the olive oil and vinegar so the soup turns creamy.", "Pass the soup through a sieve for a silky texture (optional).", "Taste and adjust the salt and vinegar.", "Chill for at least 2 hours; it must be served very cold.", "Serve in bowls or glasses topped with a little diced cucumber and a drop of olive oil."]'::jsonb, '["កាត់ប៉េងប៉ោះ ត្រសក់ដែលចិតរួច និងម្ទេសប្លោកបៃតងជាដុំធំៗ ហើយបកខ្ទឹមស។", "ដាក់ក្នុងម៉ាស៊ីនក្រឡុកជាមួយអំបិល ១ ស្លាបព្រាកាហ្វេ ហើយក្រឡុក ២ នាទី រហូតម៉ត់ល្អ។", "ពេលម៉ាស៊ីនកំពុងដំណើរការ ចាក់ប្រេងអូលីវ និងទឹកខ្មេះចូលយឺតៗ ឱ្យស៊ុបមានក្រែម។", "ចម្រោះស៊ុបតាមកន្ត្រង ដើម្បីឱ្យរលោង (ស្រេចចិត្ត)។", "ភ្លក់ ហើយកែអំបិល និងទឹកខ្មេះ។", "ដាក់ទូទឹកកកយ៉ាងតិច ២ ម៉ោង ត្រូវញ៉ាំត្រជាក់ខ្លាំង។", "ដាក់ក្នុងចាន ឬកែវ រោយត្រសក់ហាន់តូចៗ និងប្រេងអូលីវមួយដំណក់។"]'::jsonb),
('Pancakes', 'នំផេនខេក', 'Fluffy American pancakes served with honey or syrup.', 'នំផេនខេកអាមេរិកទន់ហើម ញ៉ាំជាមួយទឹកឃ្មុំ ឬទឹកស្ករ។', 430, 'US', 'sweet', 20, 2, 'easy', false, 40, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/4/40/Foodiesfeed.com_pouring-honey-on-pancakes-with-walnuts.jpg/500px-Foodiesfeed.com_pouring-honey-on-pancakes-with-walnuts.jpg', 'Photo: Mae Mu, CC0, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Foodiesfeed.com_pouring-honey-on-pancakes-with-walnuts.jpg', '["150 g flour", "2 tsp baking powder", "1 egg", "200 ml milk", "1 tbsp sugar", "Butter and honey"]'::jsonb, '["ម្សៅ ១៥០ ក្រាម", "ម្សៅដំបែ ២ ស្លាបព្រាកាហ្វេ", "ស៊ុត ១ គ្រាប់", "ទឹកដោះគោ ២០០ មីលីលីត្រ", "ស្ករ ១ ស្លាបព្រាបាយ", "ប៊ឺ និងទឹកឃ្មុំ"]'::jsonb, '["In a bowl, mix the flour, baking powder, sugar and a pinch of salt.", "In another bowl, beat the egg with the milk and 1 tbsp melted butter.", "Pour the wet mix into the dry and stir just until combined; a few lumps are fine.", "Let the batter rest 5 minutes while you heat a pan on medium-low heat.", "Wipe the pan with a little butter and pour in about 3 tbsp batter per pancake.", "Cook 2 minutes until bubbles appear on top and the edges look dry, then flip and cook 1 more minute.", "Keep the pancakes warm under a cloth while you cook the rest.", "Stack and drizzle with honey."]'::jsonb, '["ក្នុងចាន លាយម្សៅ ម្សៅដំបែ ស្ករ និងអំបិលបន្តិច។", "ក្នុងចានមួយទៀត វាយស៊ុតជាមួយទឹកដោះគោ និងប៊ឺរលាយ ១ ស្លាបព្រាបាយ។", "ចាក់ល្បាយរាវចូលក្នុងល្បាយស្ងួត ហើយកូរគ្រាន់តែលាយ មានដុំខ្លះក៏បាន។", "ទុកម្សៅ ៥ នាទី ពេលកម្តៅខ្ទះលើភ្លើងតិចមធ្យម។", "ជូតខ្ទះដោយប៊ឺបន្តិច ហើយចាក់ម្សៅប្រហែល ៣ ស្លាបព្រាបាយសម្រាប់មួយផែន។", "ចម្អិន ២ នាទី រហូតមានពពុះខាងលើ និងគែមស្ងួត រួចត្រឡប់ ហើយចម្អិន ១ នាទីទៀត។", "គ្របនំដោយក្រណាត់ ឱ្យនៅក្តៅ ពេលចម្អិននំដែលនៅសល់។", "តម្រៀបជាជង់ ហើយស្រោចទឹកឃ្មុំ។"]'::jsonb),
('Cheeseburger', 'ឈីសប៊ឺហ្គឺ', 'Grilled beef burger with melted cheese, lettuce and tomato.', 'ប៊ឺហ្គឺសាច់គោអាំង ជាមួយឈីសរលាយ សាឡាត់ និងប៉េងប៉ោះ។', 750, 'US', 'main', 20, 2, 'easy', false, 39, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/a/ac/Cheeseburger_2.jpg/500px-Cheeseburger_2.jpg', 'Photo: Kurtkaiser, CC0, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Cheeseburger_2.jpg', '["300 g ground beef", "2 burger buns", "2 slices cheese", "Lettuce and tomato", "Pickles", "Ketchup and mustard"]'::jsonb, '["សាច់គោចិញ្ច្រាំ ៣០០ ក្រាម", "នំបុ័ងប៊ឺហ្គឺ ២", "ឈីស ២ សន្លឹក", "សាឡាត់ និងប៉េងប៉ោះ", "ត្រសក់ជ្រក់", "ទឹកប៉េងប៉ោះ និងទឹកមូស្តាត"]'::jsonb, '["Divide the beef into two balls and press each into a patty slightly wider than the bun; press a dimple in the centre.", "Season both sides generously with salt and pepper just before cooking.", "Slice the tomato and pickles and wash the lettuce.", "Heat a pan or grill until very hot and cook the patties 3 minutes without moving them.", "Flip, put a slice of cheese on each and cook 2 to 3 minutes more; cover for the last minute to melt the cheese.", "Toast the cut sides of the buns in the pan for 1 minute.", "Spread the bottom buns with ketchup and mustard, then add lettuce, the patty, tomato and pickles, and close the burger."]'::jsonb, '["ចែកសាច់គោជាពីរដុំ ហើយសង្កត់នីមួយៗជាដុំសំប៉ែតធំជាងនំបុ័ងបន្តិច ហើយសង្កត់កណ្តាលឱ្យផត។", "រោយអំបិល និងម្រេចឱ្យបានច្រើនទាំងសងខាង មុនចម្អិន។", "ហាន់ប៉េងប៉ោះ និងត្រសក់ជ្រក់ ហើយលាងសាឡាត់។", "កម្តៅខ្ទះ ឬចង្ក្រានអាំងឱ្យក្តៅខ្លាំង ហើយចម្អិនសាច់ ៣ នាទី កុំរំកិល។", "ត្រឡប់ ដាក់ឈីសមួយសន្លឹកលើនីមួយៗ ហើយចម្អិន ២ ទៅ ៣ នាទីទៀត គ្របនាទីចុងក្រោយ ឱ្យឈីសរលាយ។", "អាំងផ្ទៃកាត់នៃនំបុ័ងក្នុងខ្ទះ ១ នាទី។", "លាបទឹកប៉េងប៉ោះ និងមូស្តាតលើនំបុ័ងខាងក្រោម ដាក់សាឡាត់ សាច់ ប៉េងប៉ោះ និងត្រសក់ជ្រក់ ហើយគ្របនំបុ័ង។"]'::jsonb),
('Guacamole', 'ក្វាកាម៉ូលេ', 'Mexican avocado dip with lime, onion and cilantro, served with chips.', 'ទឹកជ្រលក់ផ្លែបឺម៉ិកស៊ិក ជាមួយក្រូចឆ្មា ខ្ទឹមបារាំង និងជីវ៉ាន់ស៊ុយ។', 230, 'MX', 'snack', 10, 4, 'easy', false, 38, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f5/Guacamole_and_chips_-_Stierch.jpg/500px-Guacamole_and_chips_-_Stierch.jpg', 'Photo: Missvain, CC BY 4.0, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Guacamole_and_chips_-_Stierch.jpg', '["3 ripe avocados", "1 lime", "1 small onion", "1 tomato", "Cilantro", "Tortilla chips"]'::jsonb, '["ផ្លែបឺទុំ ៣ ផ្លែ", "ក្រូចឆ្មា ១ ផ្លែ", "ខ្ទឹមបារាំងតូច ១ មើម", "ប៉េងប៉ោះ ១ ផ្លែ", "ជីវ៉ាន់ស៊ុយ", "នំក្រៀបតតុកស៊ី"]'::jsonb, '["Chop the onion very finely and rinse it in cold water to soften its bite; drain.", "Seed the tomato and dice it small; chop a handful of cilantro.", "Halve the avocados, remove the stones and scoop the flesh into a bowl.", "Add the juice of the lime and 1/2 tsp salt and mash with a fork, leaving some chunks.", "Fold in the onion, tomato and cilantro.", "Taste and add more salt or lime if needed.", "Serve straight away with tortilla chips (lime keeps it green for a short time)."]'::jsonb, '["ចិញ្ច្រាំខ្ទឹមបារាំងឱ្យម៉ត់បំផុត ហើយលាងទឹកត្រជាក់ ដើម្បីបន្ថយការហឹរ រួចស្រង់។", "យកគ្រាប់ប៉េងប៉ោះចេញ ហើយកាត់ជាដុំតូចៗ ចិញ្ច្រាំជីវ៉ាន់ស៊ុយមួយក្តាប់។", "ពុះផ្លែបឺពាក់កណ្តាល យកគ្រាប់ចេញ ហើយកោសសាច់ដាក់ក្នុងចាន។", "ដាក់ទឹកក្រូចឆ្មា និងអំបិល ១/២ ស្លាបព្រាកាហ្វេ ហើយកិនដោយសម ទុកដុំខ្លះ។", "ច្របល់ខ្ទឹមបារាំង ប៉េងប៉ោះ និងជីវ៉ាន់ស៊ុយចូល។", "ភ្លក់ ហើយបន្ថែមអំបិល ឬក្រូចឆ្មាបើចាំបាច់។", "ញ៉ាំភ្លាមជាមួយនំក្រៀប (ក្រូចឆ្មាជួយឱ្យនៅបៃតងមួយរយៈខ្លី)។"]'::jsonb),
('Horchata', 'អរឆាតា', 'Sweet Mexican rice and cinnamon drink served over ice.', 'ភេសជ្ជៈអង្ករ និងសំបកឈើក្រអូបម៉ិកស៊ិកផ្អែម ចាក់លើទឹកកក។', 200, 'MX', 'drinks', 15, 4, 'easy', false, 37, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/6/65/Horchata%2C_my_drink_of_choice_in_Mexico_-_Merida_Yucatan_21_March_2021.jpg/500px-Horchata%2C_my_drink_of_choice_in_Mexico_-_Merida_Yucatan_21_March_2021.jpg', 'Photo: Sharon Hahn Darlin, CC BY 2.0, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Horchata,_my_drink_of_choice_in_Mexico_-_Merida_Yucatan_21_March_2021.jpg', '["150 g white rice", "1 cinnamon stick", "1 litre water", "100 g sugar", "100 ml milk", "Ice"]'::jsonb, '["អង្ករស ១៥០ ក្រាម", "សំបកឈើក្រអូប ១ ដើម", "ទឹក ១ លីត្រ", "ស្ករ ១០០ ក្រាម", "ទឹកដោះគោ ១០០ មីលីលីត្រ", "ទឹកកក"]'::jsonb, '["Rinse the rice, then put it in a jug with the cinnamon stick broken into pieces and 750 ml of the water.", "Cover and soak at room temperature for 8 hours or overnight.", "Pour everything into a blender and blend for 2 minutes until the rice is very fine.", "Strain through a fine cloth or several layers of sieve, squeezing to get all the liquid.", "Stir in the remaining water, the sugar and the milk until the sugar dissolves.", "Chill for 1 hour.", "Stir again (it settles) and serve over ice."]'::jsonb, '["លាងអង្ករ រួចដាក់ក្នុងប៉ាន់ជាមួយសំបកឈើក្រអូបបាក់ជាកង់ និងទឹក ៧៥០ មីលីលីត្រ។", "គ្រប ហើយត្រាំនៅសីតុណ្ហភាពបន្ទប់ ៨ ម៉ោង ឬមួយយប់។", "ចាក់ទាំងអស់ចូលម៉ាស៊ីនក្រឡុក ហើយក្រឡុក ២ នាទី រហូតអង្ករម៉ត់ល្អ។", "ចម្រោះតាមក្រណាត់ល្អិត ឬកន្ត្រងច្រើនជាន់ ច្របាច់ឱ្យទឹកចេញទាំងអស់។", "លាយទឹកដែលនៅសល់ ស្ករ និងទឹកដោះគោ កូររហូតស្កររលាយ។", "ដាក់ទូទឹកកក ១ ម៉ោង។", "កូរម្តងទៀត (វាតែងកករ) ហើយចាក់លើទឹកកក។"]'::jsonb),
('Lentil Soup', 'ស៊ុបសណ្តែកលីនទីល', 'Smooth Turkish red lentil soup with a squeeze of lemon.', 'ស៊ុបសណ្តែកលីនទីលក្រហមតួកគីម៉ត់ ច្របាច់ក្រូចឆ្មាបន្តិច។', 260, 'TR', 'soup', 35, 4, 'easy', false, 36, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/6/6e/Homemade_Lentil_Soup_-_Lavash_2025-02-10.jpg/500px-Homemade_Lentil_Soup_-_Lavash_2025-02-10.jpg', 'Photo: Andy Li, CC0, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Homemade_Lentil_Soup_-_Lavash_2025-02-10.jpg', '["200 g red lentils", "1 onion", "1 carrot", "1 tbsp tomato paste", "1 litre stock", "1 lemon"]'::jsonb, '["សណ្តែកលីនទីលក្រហម ២០០ ក្រាម", "ខ្ទឹមបារាំង ១ មើម", "ការ៉ុត ១ មើម", "ប៉េងប៉ោះខាប់ ១ ស្លាបព្រាបាយ", "ទឹកស៊ុប ១ លីត្រ", "ក្រូចឆ្មា ១ ផ្លែ"]'::jsonb, '["Rinse the lentils in a sieve until the water runs clear.", "Chop the onion and grate or dice the carrot.", "Heat 2 tbsp oil in a pot and cook the onion and carrot on medium heat for 5 minutes until soft.", "Stir in the tomato paste and cook 1 minute.", "Add the lentils and stock, bring to the boil, then simmer 25 minutes until the lentils fall apart.", "Blend the soup until smooth; add a little hot water if it is too thick.", "Season with salt and pepper.", "Serve hot with lemon wedges to squeeze over."]'::jsonb, '["លាងសណ្តែកក្នុងកន្ត្រងរហូតទឹកថ្លា។", "ចិញ្ច្រាំខ្ទឹមបារាំង ហើយកោស ឬកាត់ការ៉ុតតូចៗ។", "កម្តៅប្រេង ២ ស្លាបព្រាបាយក្នុងឆ្នាំង ហើយឆាខ្ទឹមបារាំង និងការ៉ុតភ្លើងមធ្យម ៥ នាទី រហូតទន់។", "ដាក់ប៉េងប៉ោះខាប់ ហើយចម្អិន ១ នាទី។", "ដាក់សណ្តែក និងទឹកស៊ុប ស្ងោរឱ្យពុះ រួចរំងាស់ ២៥ នាទី រហូតសណ្តែករលួយ។", "ក្រឡុកស៊ុបឱ្យម៉ត់ ដាក់ទឹកក្តៅបន្តិចបើខាប់ពេក។", "ដាក់អំបិល និងម្រេច។", "ញ៉ាំក្តៅៗជាមួយក្រូចឆ្មាសម្រាប់ច្របាច់។"]'::jsonb),
('Baklava', 'បាក្លាវ៉ា', 'Layers of crisp filo pastry with nuts, soaked in sweet syrup.', 'នំស្រទាប់ស្តើងៗស្រួយ ជាមួយគ្រាប់ធញ្ញជាតិ ត្រាំទឹកស្ករ។', 420, 'TR', 'sweet', 90, 12, 'hard', false, 35, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c5/Baklava_in_pan.jpg/500px-Baklava_in_pan.jpg', 'Photo: Punker1999, CC0, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Baklava_in_pan.jpg', '["500 g filo pastry", "250 g butter, melted", "300 g chopped pistachios or walnuts", "300 g sugar", "200 ml water", "1 tbsp lemon juice"]'::jsonb, '["ស្លឹកម្សៅហ្វីឡូ ៥០០ ក្រាម", "ប៊ឺរលាយ ២៥០ ក្រាម", "គ្រាប់ពីស្តាស ឬវ៉ាល់ណាត់ហាន់ ៣០០ ក្រាម", "ស្ករ ៣០០ ក្រាម", "ទឹក ២០០ មីលីលីត្រ", "ទឹកក្រូចឆ្មា ១ ស្លាបព្រាបាយ"]'::jsonb, '["Make the syrup first: boil the sugar and water for 10 minutes, add the lemon juice and let it cool completely.", "Heat the oven to 170 °C and brush a baking tray with melted butter.", "Keep the filo under a damp cloth so it does not dry out.", "Lay a sheet of filo in the tray, brush it with butter, and repeat until you have used half the sheets.", "Spread the chopped nuts evenly over the pastry.", "Cover with the rest of the filo, buttering each sheet, and brush the top well.", "With a sharp knife, cut all the way through into diamonds or squares.", "Bake 45 minutes until deep golden and crisp.", "Pour the cold syrup over the hot baklava as soon as it comes out, then leave at least 4 hours before serving."]'::jsonb, '["ធ្វើទឹកស្ករមុន៖ ដាំស្ករ និងទឹក ១០ នាទី ដាក់ទឹកក្រូចឆ្មា ហើយទុកឱ្យត្រជាក់ទាំងស្រុង។", "កម្តៅឡ ១៧០ អង្សា ហើយលាបប៊ឺរលាយលើថាសដុត។", "គ្របស្លឹកហ្វីឡូដោយក្រណាត់សើម ដើម្បីកុំឱ្យស្ងួត។", "ក្រាលហ្វីឡូមួយសន្លឹកក្នុងថាស លាបប៊ឺ ហើយធ្វើម្តងទៀតរហូតប្រើអស់ពាក់កណ្តាល។", "រោយគ្រាប់ហាន់ឱ្យស្មើលើស្រទាប់។", "គ្របដោយហ្វីឡូដែលនៅសល់ លាបប៊ឺគ្រប់សន្លឹក ហើយលាបខាងលើឱ្យល្អ។", "ប្រើកាំបិតមុត កាត់ឱ្យដាច់ដល់បាតជារាងពេជ្រ ឬការ៉េ។", "ដុត ៤៥ នាទី រហូតលឿងចាស់ និងស្រួយ។", "ចាក់ទឹកស្ករត្រជាក់លើនំក្តៅភ្លាមពេលយកចេញ ហើយទុកយ៉ាងតិច ៤ ម៉ោងមុនញ៉ាំ។"]'::jsonb),
('Greek Salad', 'សាឡាត់ក្រិក', 'Tomato, cucumber, olives and feta with olive oil and oregano.', 'ប៉េងប៉ោះ ត្រសក់ ផ្លែអូលីវ និងឈីសហ្វេតា ជាមួយប្រេងអូលីវ។', 280, 'GR', 'salad', 10, 2, 'easy', false, 34, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5f/Greek_Salad_Choriatiki.jpg/500px-Greek_Salad_Choriatiki.jpg', 'Photo: https://www.flickr.com/photos/zone41/, CC BY 2.0, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Greek_Salad_Choriatiki.jpg', '["3 tomatoes", "1 cucumber", "1 red onion", "100 g feta cheese", "10 olives", "2 tbsp olive oil and oregano"]'::jsonb, '["ប៉េងប៉ោះ ៣ ផ្លែ", "ត្រសក់ ១ ផ្លែ", "ខ្ទឹមបារាំងក្រហម ១ មើម", "ឈីសហ្វេតា ១០០ ក្រាម", "ផ្លែអូលីវ ១០ គ្រាប់", "ប្រេងអូលីវ ២ ស្លាបព្រាបាយ និងអូរេហ្គាណូ"]'::jsonb, '["Cut the tomatoes into wedges and the cucumber into thick half-moons.", "Slice the red onion into thin rings.", "Put the tomatoes, cucumber and onion in a bowl and season lightly with salt.", "Add the olives.", "Place the block of feta whole on top.", "Drizzle generously with olive oil, sprinkle oregano over the feta and serve with bread."]'::jsonb, '["កាត់ប៉េងប៉ោះជាចំណិត ហើយកាត់ត្រសក់ជាកង់ពាក់កណ្តាលក្រាស់ៗ។", "ហាន់ខ្ទឹមបារាំងក្រហមជាកងស្តើងៗ។", "ដាក់ប៉េងប៉ោះ ត្រសក់ និងខ្ទឹមបារាំងក្នុងចាន ហើយដាក់អំបិលបន្តិច។", "ដាក់ផ្លែអូលីវ។", "ដាក់ឈីសហ្វេតាមួយដុំទាំងមូលពីលើ។", "ស្រោចប្រេងអូលីវឱ្យច្រើន រោយអូរេហ្គាណូលើឈីស ហើយញ៉ាំជាមួយនំបុ័ង។"]'::jsonb),
('Moussaka', 'មូសាកា', 'Baked layers of eggplant, spiced meat sauce and creamy white sauce.', 'ត្រប់ ទឹកសាច់គ្រឿងទេស និងទឹកក្រែមស ដុតជាស្រទាប់ៗ។', 620, 'GR', 'main', 90, 6, 'hard', false, 33, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/0/08/Meat_Moussaka_-_Kouzina%2C_Brighton_2023-11-24.jpg/500px-Meat_Moussaka_-_Kouzina%2C_Brighton_2023-11-24.jpg', 'Photo: Andy Li, CC0, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Meat_Moussaka_-_Kouzina,_Brighton_2023-11-24.jpg', '["3 eggplants", "500 g minced lamb or beef", "400 g crushed tomatoes", "1 onion", "1 tsp cinnamon", "500 ml white sauce"]'::jsonb, '["ត្រប់ ៣ ផ្លែ", "សាច់ចៀម ឬសាច់គោចិញ្ច្រាំ ៥០០ ក្រាម", "ប៉េងប៉ោះកិន ៤០០ ក្រាម", "ខ្ទឹមបារាំង ១ មើម", "ម្សៅសំបកឈើក្រអូប ១ ស្លាបព្រាកាហ្វេ", "ទឹកក្រែមស ៥០០ មីលីលីត្រ"]'::jsonb, '["Cut the eggplants into 1 cm slices, salt them and leave 20 minutes; pat dry.", "Brush the slices with oil and roast at 200 °C for 20 minutes, or fry until golden; set aside.", "Chop the onion and fry it in 1 tbsp oil for 5 minutes, then add the meat and cook until browned.", "Add the crushed tomatoes, cinnamon, salt and pepper and simmer 20 minutes until thick.", "Lower the oven to 180 °C.", "In a baking dish, layer half the eggplant, all the meat sauce, then the rest of the eggplant.", "Pour the white sauce over the top and smooth it.", "Bake 45 minutes until the top is golden.", "Rest 20 minutes before cutting, so the layers hold together."]'::jsonb, '["កាត់ត្រប់ជាចំណិតក្រាស់ ១ សង់ទីម៉ែត្រ រោយអំបិល ហើយទុក ២០ នាទី រួចជូតឱ្យស្ងួត។", "លាបប្រេងលើចំណិតត្រប់ ហើយដុត ២០០ អង្សា ២០ នាទី ឬចៀនរហូតលឿង រួចទុកមួយឡែក។", "ចិញ្ច្រាំខ្ទឹមបារាំង ហើយលីងក្នុងប្រេង ១ ស្លាបព្រាបាយ ៥ នាទី រួចដាក់សាច់ ហើយឆារហូតឡើងពណ៌។", "ដាក់ប៉េងប៉ោះកិន សំបកឈើក្រអូប អំបិល និងម្រេច ហើយរំងាស់ ២០ នាទី រហូតខាប់។", "បន្ថយកម្តៅឡមក ១៨០ អង្សា។", "ក្នុងថាសដុត រៀបត្រប់ពាក់កណ្តាល ទឹកសាច់ទាំងអស់ រួចត្រប់ដែលនៅសល់។", "ចាក់ទឹកក្រែមសពីលើ ហើយរីកឱ្យស្មើ។", "ដុត ៤៥ នាទី រហូតខាងលើពណ៌មាស។", "ទុក ២០ នាទីមុនកាត់ ដើម្បីឱ្យស្រទាប់នៅជាប់គ្នា។"]'::jsonb),
('Fish and Chips', 'ត្រីចៀន និងដំឡូងបំពង', 'British battered fried fish with thick chips and mushy peas.', 'ត្រីស្រោបម្សៅចៀនបែបអង់គ្លេស ជាមួយដំឡូងបំពងក្រាស់ និងសណ្តែកបារាំងកិន។', 840, 'GB', 'main', 40, 2, 'medium', false, 32, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/8/88/Fish_and_chips_-_Twickenham%2C_UK.jpg/500px-Fish_and_chips_-_Twickenham%2C_UK.jpg', 'Photo: Daderot, CC0, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Fish_and_chips_-_Twickenham,_UK.jpg', '["2 white fish fillets", "150 g flour", "200 ml cold sparkling water", "3 large potatoes", "Oil for frying", "Lemon and mushy peas"]'::jsonb, '["សាច់ត្រីស ២ ដុំ", "ម្សៅ ១៥០ ក្រាម", "ទឹកសូដាត្រជាក់ ២០០ មីលីលីត្រ", "ដំឡូងបារាំងធំ ៣ មើម", "ប្រេងសម្រាប់ចៀន", "ក្រូចឆ្មា និងសណ្តែកបារាំងកិន"]'::jsonb, '["Peel the potatoes and cut them into thick chips, about 1.5 cm; rinse in cold water and dry well on a towel.", "Heat the oil in a deep pot to 150 °C and fry the chips in batches for 6 to 8 minutes until soft but still pale; drain.", "Pat the fish dry and season with salt.", "Whisk the flour, a pinch of salt and the cold sparkling water into a smooth batter, just before frying.", "Raise the oil to 180 °C. Dust the fish in a little flour, dip it in the batter and lower it gently into the oil.", "Fry 5 to 6 minutes, turning once, until golden and crisp; drain on paper.", "Fry the chips again at 180 °C for 2 to 3 minutes until golden and crunchy; salt them straight away.", "Serve the fish and chips with lemon wedges and warm mushy peas."]'::jsonb, '["ចិតដំឡូង ហើយកាត់ជាបន្ទះក្រាស់ប្រហែល ១,៥ សង់ទីម៉ែត្រ លាងទឹកត្រជាក់ ហើយជូតឱ្យស្ងួតដោយកន្សែង។", "កម្តៅប្រេងក្នុងឆ្នាំងជ្រៅដល់ ១៥០ អង្សា ហើយចៀនដំឡូងម្តងមួយចំណែក ៦ ទៅ ៨ នាទី រហូតទន់ តែនៅស រួចស្រង់។", "ជូតត្រីឱ្យស្ងួត ហើយរោយអំបិល។", "វាយម្សៅ អំបិលបន្តិច និងទឹកសូដាត្រជាក់ឱ្យម៉ត់ មុនចៀនភ្លាម។", "បង្កើនប្រេងដល់ ១៨០ អង្សា។ ប្រឡាក់ត្រីនឹងម្សៅបន្តិច ជ្រលក់ម្សៅរាវ ហើយដាក់ចូលប្រេងថ្នមៗ។", "ចៀន ៥ ទៅ ៦ នាទី ត្រឡប់ម្តង រហូតលឿងស្រួយ ហើយស្រង់លើក្រដាស។", "ចៀនដំឡូងម្តងទៀតនៅ ១៨០ អង្សា ២ ទៅ ៣ នាទី រហូតលឿងស្រួយ ហើយរោយអំបិលភ្លាម។", "ញ៉ាំត្រី និងដំឡូងជាមួយក្រូចឆ្មា និងសណ្តែកបារាំងកិនក្តៅៗ។"]'::jsonb),
('Shepherd''s Pie', 'នំដុតសាច់ចៀមដំឡូង', 'Minced lamb in rich gravy, baked under a golden mashed potato crust.', 'សាច់ចៀមចិញ្ច្រាំក្នុងទឹកខាប់ ដុតក្រោមស្រទាប់ដំឡូងកិនពណ៌មាស។', 560, 'GB', 'main', 75, 4, 'medium', false, 31, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b0/Shepherds_pie_-_The_Kew_Greenhouse_Cafe_2025-05-14.jpg/500px-Shepherds_pie_-_The_Kew_Greenhouse_Cafe_2025-05-14.jpg', 'Photo: Andy Li, CC0, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Shepherds_pie_-_The_Kew_Greenhouse_Cafe_2025-05-14.jpg', '["500 g minced lamb", "1 onion and 1 carrot", "1 tbsp tomato paste", "300 ml stock", "800 g potatoes", "50 g butter and a splash of milk"]'::jsonb, '["សាច់ចៀមចិញ្ច្រាំ ៥០០ ក្រាម", "ខ្ទឹមបារាំង ១ និងការ៉ុត ១", "ប៉េងប៉ោះខាប់ ១ ស្លាបព្រាបាយ", "ទឹកស៊ុប ៣០០ មីលីលីត្រ", "ដំឡូងបារាំង ៨០០ ក្រាម", "ប៊ឺ ៥០ ក្រាម និងទឹកដោះគោបន្តិច"]'::jsonb, '["Peel the potatoes, cut into chunks and boil in salted water for 15 to 20 minutes until soft.", "Meanwhile chop the onion and carrot and fry them in 1 tbsp oil for 5 minutes.", "Add the lamb and cook on high heat, breaking it up, until browned all over.", "Stir in the tomato paste for 1 minute, then add the stock, salt and pepper.", "Simmer 20 minutes until the gravy is thick; spoon it into a baking dish.", "Heat the oven to 200 °C. Drain the potatoes and mash with the butter and milk until smooth; season with salt.", "Spread the mash over the meat and roughen the top with a fork so it crisps.", "Bake 25 minutes until golden and bubbling at the edges; rest 5 minutes before serving."]'::jsonb, '["ចិតដំឡូង កាត់ជាដុំ ហើយស្ងោរក្នុងទឹកអំបិល ១៥ ទៅ ២០ នាទី រហូតទន់។", "ក្នុងពេលនោះ ចិញ្ច្រាំខ្ទឹមបារាំង និងការ៉ុត ហើយឆាក្នុងប្រេង ១ ស្លាបព្រាបាយ ៥ នាទី។", "ដាក់សាច់ចៀម ហើយឆាលើភ្លើងខ្លាំង កូរញែក រហូតឡើងពណ៌សព្វ។", "ដាក់ប៉េងប៉ោះខាប់ កូរ ១ នាទី រួចដាក់ទឹកស៊ុប អំបិល និងម្រេច។", "រំងាស់ ២០ នាទី រហូតទឹកខាប់ ហើយដួសដាក់ក្នុងថាសដុត។", "កម្តៅឡ ២០០ អង្សា។ ស្រង់ដំឡូង ហើយកិនជាមួយប៊ឺ និងទឹកដោះគោឱ្យម៉ត់ ដាក់អំបិល។", "ពង្រាយដំឡូងកិនលើសាច់ ហើយកោសខាងលើដោយសម ឱ្យវាស្រួយ។", "ដុត ២៥ នាទី រហូតពណ៌មាស និងពុះតាមគែម ទុក ៥ នាទីមុនញ៉ាំ។"]'::jsonb)
